-- Stop early, with a clear message, if the earlier migrations haven't been run on this project.
do $$
begin
  if to_regclass('public.compliance_requirements') is null or to_regclass('public.compliance_guides') is null
     or to_regclass('public.checklist_items') is null or to_regclass('public.agent_keys') is null then
    raise exception 'Run the first six files in supabase/migrations first (init up to compliance_register), then run this file again.';
  end if;
end $$;

-- ============================================================================
-- supabase/migrations/20261026110000_compliance_agent.sql
-- ============================================================================
-- Beehive Compliance Agent (see AGENT.md).
-- The agent reviews staff credentials, then saves renewal-reminder DRAFTS and owner escalations.
-- It cannot send anything, approve certificates or change staff records: the owner approves every
-- reminder on the Compliance page. All agent functions are scoped to one centre by its agent key.

create table if not exists public.staff_reminder_drafts (
  id                   uuid primary key default gen_random_uuid(),
  centre_id            uuid not null references public.centres (id) on delete cascade,
  staff_id             uuid not null references public.staff (id) on delete cascade,
  certificate_type_id  uuid references public.certificate_types (id),
  kind                 text not null check (kind in ('renewal', 'missing', 'follow_up', 'escalation')),
  priority             text not null default 'medium' check (priority in ('high', 'medium', 'low')),
  reason               text not null default '',
  body                 text not null default '',          -- message to the educator (empty for escalations)
  follow_up_on         date,                              -- when to check again if still outstanding
  status               text not null default 'draft' check (status in ('draft', 'sent', 'discarded', 'resolved')),
  created_by           text not null default 'agent',
  created_at           timestamptz not null default now(),
  decided_by           uuid references public.users (id) on delete set null,
  decided_at           timestamptz
);
create index if not exists staff_reminder_drafts_centre_idx on public.staff_reminder_drafts (centre_id, status, created_at desc);

alter table public.staff_reminder_drafts enable row level security;
drop policy if exists "leaders read reminder drafts" on public.staff_reminder_drafts;
create policy "leaders read reminder drafts" on public.staff_reminder_drafts for select
  using (centre_id = public.my_centre_id() and public.is_leader());
drop policy if exists "educators read their sent reminders" on public.staff_reminder_drafts;
create policy "educators read their sent reminders" on public.staff_reminder_drafts for select
  using (status = 'sent' and kind <> 'escalation'
         and exists (select 1 from public.staff s where s.id = staff_id and s.user_id = auth.uid()));
-- No insert/update/delete policies: changes only happen through the functions below.
grant select on public.staff_reminder_drafts to authenticated;

-- Which credentials every educator must hold (matches the staff register).
create or replace function public._required_cert_codes()
returns text[] language sql immutable as $$ select array['WWCC', 'FIRST_AID', 'CPR', 'ANAPHYLAXIS'] $$;

-- One row per educator per required credential, with what the agent needs to decide.
drop function if exists public._credential_review(uuid);
create or replace function public._credential_review(p_centre uuid)
returns table (staff_id uuid, staff_name text, room text, has_login boolean, certificate_code text, certificate_name text,
               status text, expiry_date date, days_left int, reminder_window int,
               last_reminder_sent date, renewal_submitted boolean, open_draft boolean, escalation_open boolean, follow_up_due boolean)
language sql stable security definer set search_path = public as $$
  select s.id, s.full_name, coalesce(nullif(s.room, ''), '—'), s.user_id is not null, ct.code, ct.name,
         case when sc.id is null then 'missing'
              when not ct.expires or sc.expiry_date is null then 'valid'
              when sc.expiry_date < current_date then 'expired'
              when sc.expiry_date <= current_date + ct.reminder_days then 'expiring_soon'
              else 'valid' end,
         sc.expiry_date,
         case when sc.expiry_date is null then null else sc.expiry_date - current_date end,
         ct.reminder_days,
         greatest((select max(r.sent_at)::date from reminders r where r.staff_certificate_id = sc.id and r.status = 'sent'),
                  (select max(d.decided_at)::date from staff_reminder_drafts d where d.staff_id = s.id and d.certificate_type_id = ct.id and d.status = 'sent')),
         exists (select 1 from certificate_submissions cs where cs.staff_id = s.id and cs.certificate_type_id = ct.id and cs.status = 'pending'),
         exists (select 1 from staff_reminder_drafts d where d.staff_id = s.id and d.certificate_type_id = ct.id and d.status = 'draft' and d.kind <> 'escalation'),
         exists (select 1 from staff_reminder_drafts d where d.staff_id = s.id and d.certificate_type_id = ct.id and d.status = 'draft' and d.kind = 'escalation'),
         exists (select 1 from staff_reminder_drafts d where d.staff_id = s.id and d.certificate_type_id = ct.id and d.status = 'sent'
                   and d.follow_up_on <= current_date)
  from staff s
  cross join certificate_types ct
  left join lateral (select x.* from staff_certificates x where x.staff_id = s.id and x.certificate_type_id = ct.id
                     order by x.expiry_date desc nulls last limit 1) sc on true
  where s.centre_id = p_centre and s.is_active and ct.code = any (_required_cert_codes())
    and s.position not ilike '%owner%';
$$;
revoke execute on function public._credential_review(uuid) from public, anon, authenticated;

-- AGENT TOOL 1: read. Only credentials that need attention, plus counts.
create or replace function public.agent_credential_review(p_key text)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare v_centre uuid := _agent_centre(p_key);
begin
  return jsonb_build_object(
    'today', current_date,
    'required_credentials', _required_cert_codes(),
    'educators_checked', (select count(distinct staff_id) from _credential_review(v_centre)),
    'needs_attention', coalesce((
      select jsonb_agg(jsonb_build_object(
               'staff', r.staff_name, 'room', r.room, 'certificate', r.certificate_code, 'certificate_name', r.certificate_name,
               'status', r.status, 'expiry_date', r.expiry_date, 'days_left', r.days_left, 'reminder_window_days', r.reminder_window,
               'last_reminder_sent', r.last_reminder_sent, 'renewal_submitted', r.renewal_submitted,
               'draft_already_waiting', r.open_draft, 'escalation_open', r.escalation_open, 'follow_up_due', r.follow_up_due, 'has_beehive_login', r.has_login)
             order by case r.status when 'expired' then 0 when 'missing' then 1 else 2 end, r.days_left nulls first)
      from _credential_review(v_centre) r
      where r.status in ('expired', 'missing', 'expiring_soon')), '[]'::jsonb));
end $$;

-- AGENT TOOL 2: save reminder drafts (one call, many drafts). Every input is checked here,
-- so the rules hold even if the model ignores its instructions.
create or replace function public.agent_save_reminder_drafts(p_key text, p_drafts jsonb)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_centre uuid := _agent_centre(p_key);
  d jsonb; v_staff staff; v_type certificate_types; v_rev record; v_body text; v_kind text; v_prio text; v_days int;
  v_saved jsonb := '[]'::jsonb; v_skipped jsonb := '[]'::jsonb; v_id uuid; v_n int;
begin
  if jsonb_typeof(p_drafts) <> 'array' then raise exception 'drafts must be a list'; end if;
  if jsonb_array_length(p_drafts) > 15 then raise exception 'At most 15 drafts per run'; end if;
  for d in select * from jsonb_array_elements(p_drafts) loop
    v_body := trim(coalesce(d->>'body', ''));
    v_kind := coalesce(d->>'kind', 'renewal');
    v_prio := coalesce(d->>'priority', 'medium');
    v_days := coalesce(nullif(d->>'follow_up_in_days', '')::int, 7);
    select count(*) into v_n from staff where centre_id = v_centre and is_active and lower(full_name) = lower(trim(d->>'staff'));
    if v_n <> 1 then v_skipped := v_skipped || jsonb_build_object('staff', d->>'staff', 'reason', 'No single active educator with that exact name'); continue; end if;
    select * into v_staff from staff where centre_id = v_centre and is_active and lower(full_name) = lower(trim(d->>'staff'));
    select * into v_type from certificate_types where code = upper(replace(trim(coalesce(d->>'certificate', '')), ' ', '_'));
    if v_type.id is null or not (v_type.code = any (_required_cert_codes())) then
      v_skipped := v_skipped || jsonb_build_object('staff', v_staff.full_name, 'reason', 'Unknown or not-required certificate'); continue; end if;
    select * into v_rev from _credential_review(v_centre) r where r.staff_id = v_staff.id and r.certificate_code = v_type.code;
    if v_rev.status = 'valid' then
      v_skipped := v_skipped || jsonb_build_object('staff', v_staff.full_name, 'certificate', v_type.code, 'reason', 'Certificate is current; no reminder needed'); continue; end if;
    if v_rev.renewal_submitted then
      v_skipped := v_skipped || jsonb_build_object('staff', v_staff.full_name, 'certificate', v_type.code, 'reason', 'Renewal already submitted; the owner must review it'); continue; end if;
    if v_rev.open_draft then
      v_skipped := v_skipped || jsonb_build_object('staff', v_staff.full_name, 'certificate', v_type.code, 'reason', 'A draft is already waiting for approval'); continue; end if;
    if v_kind not in ('renewal', 'missing', 'follow_up') then v_kind := 'renewal'; end if;
    if v_prio not in ('high', 'medium', 'low') then v_prio := 'medium'; end if;
    if length(v_body) < 20 or length(v_body) > 900 then
      v_skipped := v_skipped || jsonb_build_object('staff', v_staff.full_name, 'reason', 'Message must be 20 to 900 characters'); continue; end if;
    if v_days < 1 or v_days > 30 then v_days := 7; end if;
    insert into staff_reminder_drafts (centre_id, staff_id, certificate_type_id, kind, priority, reason, body, follow_up_on)
    values (v_centre, v_staff.id, v_type.id, v_kind, v_prio, left(coalesce(d->>'reason', ''), 300), v_body, current_date + v_days)
    returning id into v_id;
    perform log_audit(v_centre, 'agent.reminder_drafted', 'staff_reminder_drafts', v_id::text,
      jsonb_build_object('staff_id', v_staff.id, 'certificate', v_type.code, 'kind', v_kind, 'by', 'Beehive Compliance Agent'));
    v_saved := v_saved || jsonb_build_object('staff', v_staff.full_name, 'certificate', v_type.code, 'draft_id', v_id, 'follow_up_on', current_date + v_days);
  end loop;
  return jsonb_build_object('saved', v_saved, 'skipped', v_skipped,
    'note', 'Saved as drafts. Nothing has been sent. The owner approves each reminder in Beehive.');
end $$;

-- AGENT TOOL 3: escalate to the owner (no message to the educator).
create or replace function public.agent_flag_for_owner(p_key text, p_items jsonb)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_centre uuid := _agent_centre(p_key); d jsonb; v_staff staff; v_type uuid; v_id uuid; v_out jsonb := '[]'::jsonb; v_n int;
begin
  if jsonb_typeof(p_items) <> 'array' then raise exception 'items must be a list'; end if;
  if jsonb_array_length(p_items) > 15 then raise exception 'At most 15 escalations per run'; end if;
  for d in select * from jsonb_array_elements(p_items) loop
    select count(*) into v_n from staff where centre_id = v_centre and is_active and lower(full_name) = lower(trim(d->>'staff'));
    if v_n <> 1 then continue; end if;
    select * into v_staff from staff where centre_id = v_centre and is_active and lower(full_name) = lower(trim(d->>'staff'));
    select id into v_type from certificate_types where code = upper(replace(trim(coalesce(d->>'certificate', '')), ' ', '_'));
    if exists (select 1 from staff_reminder_drafts x where x.staff_id = v_staff.id and x.kind = 'escalation' and x.status = 'draft'
               and x.certificate_type_id is not distinct from v_type) then continue; end if;
    insert into staff_reminder_drafts (centre_id, staff_id, certificate_type_id, kind, priority, reason)
    values (v_centre, v_staff.id, v_type, 'escalation', 'high', left(coalesce(d->>'reason', 'Needs the owner''s decision'), 300))
    returning id into v_id;
    perform log_audit(v_centre, 'agent.escalated', 'staff_reminder_drafts', v_id::text,
      jsonb_build_object('staff_id', v_staff.id, 'reason', d->>'reason', 'by', 'Beehive Compliance Agent'));
    v_out := v_out || jsonb_build_object('staff', v_staff.full_name, 'escalation_id', v_id);
  end loop;
  return jsonb_build_object('escalated', v_out, 'note', 'Flagged for the owner. The agent has not contacted anyone.');
end $$;

grant execute on function public.agent_credential_review(text) to anon, authenticated;
grant execute on function public.agent_save_reminder_drafts(text, jsonb) to anon, authenticated;
grant execute on function public.agent_flag_for_owner(text, jsonb) to anon, authenticated;

-- OWNER ACTIONS (Compliance page). Approving records the reminder as sent and schedules the follow-up.
create or replace function public.approve_staff_reminder(p_id uuid, p_body text default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_d staff_reminder_drafts; v_cert uuid;
begin
  if not is_leader() then raise exception 'Only the owner or director can approve reminders'; end if;
  select * into v_d from staff_reminder_drafts where id = p_id and centre_id = my_centre_id();
  if not found then raise exception 'Reminder not found'; end if;
  if v_d.status <> 'draft' or v_d.kind = 'escalation' then raise exception 'This reminder has already been handled'; end if;
  update staff_reminder_drafts set status = 'sent', body = coalesce(nullif(trim(p_body), ''), body), decided_by = auth.uid(), decided_at = now()
   where id = p_id;
  select id into v_cert from staff_certificates where staff_id = v_d.staff_id and certificate_type_id = v_d.certificate_type_id
   order by expiry_date desc nulls last limit 1;
  if v_cert is not null then
    insert into reminders (staff_certificate_id, channel, send_at, status, sent_at) values (v_cert, 'in_app', now(), 'sent', now());
  end if;
  perform log_audit(v_d.centre_id, 'staff_reminder.sent', 'staff_reminder_drafts', p_id::text,
    jsonb_build_object('staff_id', v_d.staff_id, 'drafted_by_agent', v_d.created_by = 'agent', 'follow_up_on', v_d.follow_up_on));
  return jsonb_build_object('sent', true, 'follow_up_on', v_d.follow_up_on);
end $$;

create or replace function public.decide_staff_reminder(p_id uuid, p_decision text)
returns void language plpgsql security definer set search_path = public as $$
declare v_d staff_reminder_drafts;
begin
  if not is_leader() then raise exception 'Only the owner or director can do this'; end if;
  if p_decision not in ('discarded', 'resolved') then raise exception 'Unknown decision'; end if;
  select * into v_d from staff_reminder_drafts where id = p_id and centre_id = my_centre_id();
  if not found then raise exception 'Item not found'; end if;
  if v_d.status <> 'draft' then raise exception 'This item has already been handled'; end if;
  update staff_reminder_drafts set status = p_decision, decided_by = auth.uid(), decided_at = now() where id = p_id;
  perform log_audit(v_d.centre_id, 'staff_reminder.' || p_decision, 'staff_reminder_drafts', p_id::text, jsonb_build_object('kind', v_d.kind));
end $$;

grant execute on function public.approve_staff_reminder(uuid, text) to authenticated;
grant execute on function public.decide_staff_reminder(uuid, text) to authenticated;

-- What the owner sees on the Compliance page.
create or replace view public.v_staff_reminder_queue with (security_invoker = on) as
select d.id, d.centre_id, d.kind, d.priority, d.reason, d.body, d.follow_up_on, d.status, d.created_at, d.decided_at,
       s.full_name as staff_name, coalesce(nullif(s.room, ''), '—') as room, ct.code as certificate_code, ct.name as certificate_name
from public.staff_reminder_drafts d
join public.staff s on s.id = d.staff_id
left join public.certificate_types ct on ct.id = d.certificate_type_id;
grant select on public.v_staff_reminder_queue to authenticated;

-- ============================================================================
-- supabase/migrations/20261028090000_staff_agent.sql
-- ============================================================================
-- beehive staff compliance agent
-- A monitoring and action loop for staff credentials that runs without the owner:
-- detect -> prioritise -> request (simulated email/SMS) -> wait -> follow up -> process upload
-- -> owner verification -> update record -> resolve, escalating anything critical.
--
-- Priority, used everywhere (database and interface):
--   critical  expired or missing
--   high      expires within 7 days
--   medium    expires within 30 days
--   monitor   expires within the reminder window (60 days)
--
-- Task states: monitoring, waiting (request out), owner_review (upload or escalation needs the
-- owner), resolved. Every step is written to agent_events (the activity feed) and audit_log.
-- Messages are SIMULATED: they are recorded with recipient and timestamp but nothing leaves beehive.

-- ---------------------------------------------------------------------------
-- tables
-- ---------------------------------------------------------------------------
create table if not exists public.credential_tasks (
  id                   uuid primary key default gen_random_uuid(),
  centre_id            uuid not null references public.centres (id) on delete cascade,
  staff_id             uuid not null references public.staff (id) on delete cascade,
  certificate_type_id  uuid not null references public.certificate_types (id),
  priority             text not null check (priority in ('critical', 'high', 'medium', 'monitor')),
  state                text not null default 'monitoring' check (state in ('monitoring', 'waiting', 'owner_review', 'resolved')),
  reason               text not null default '',
  expiry_date          date,
  requests_sent        int not null default 0,
  last_request_at      timestamptz,
  next_follow_up       date,
  escalated_at         timestamptz,
  escalation_reason    text,
  recommended_action   text,
  escalation_ack_at    timestamptz,
  upload_token         uuid not null default gen_random_uuid(),
  opened_at            timestamptz not null default now(),
  updated_at           timestamptz not null default now(),
  resolved_at          timestamptz,
  resolution           text
);
create unique index if not exists credential_tasks_open_idx on public.credential_tasks (staff_id, certificate_type_id) where state <> 'resolved';
create unique index if not exists credential_tasks_token_idx on public.credential_tasks (upload_token);
create index if not exists credential_tasks_centre_idx on public.credential_tasks (centre_id, state);

create table if not exists public.agent_messages (
  id           uuid primary key default gen_random_uuid(),
  centre_id    uuid not null references public.centres (id) on delete cascade,
  task_id      uuid references public.credential_tasks (id) on delete cascade,
  staff_id     uuid not null references public.staff (id) on delete cascade,
  kind         text not null check (kind in ('request', 'follow_up', 'correction')),
  channel      text not null check (channel in ('email', 'sms', 'none')),
  recipient    text not null default '',
  subject      text not null default '',
  body         text not null,
  upload_link  text not null default '',
  outcome      text not null default 'simulated' check (outcome in ('simulated', 'no_contact')),
  sent_at      timestamptz not null default now(),
  next_follow_up date
);
create index if not exists agent_messages_staff_idx on public.agent_messages (staff_id, sent_at desc);

create table if not exists public.agent_events (
  id                   bigint generated always as identity primary key,
  centre_id            uuid not null references public.centres (id) on delete cascade,
  task_id              uuid references public.credential_tasks (id) on delete cascade,
  staff_id             uuid references public.staff (id) on delete cascade,
  certificate_type_id  uuid references public.certificate_types (id),
  kind                 text not null,   -- detected, reprioritised, request_sent, follow_up_sent, upload_received, flagged,
                                        -- approved, rejected, correction_requested, record_updated, escalated,
                                        -- escalation_acknowledged, resolved, no_contact
  state                text not null check (state in ('Monitoring', 'Action taken', 'Waiting', 'Owner review', 'Resolved')),
  summary              text not null,
  detail               jsonb not null default '{}',
  demo                 boolean not null default false,
  created_at           timestamptz not null default now()
);
create index if not exists agent_events_centre_idx on public.agent_events (centre_id, created_at desc);

create table if not exists public.agent_runs (
  id          bigint generated always as identity primary key,
  centre_id   uuid not null references public.centres (id) on delete cascade,
  trigger     text not null default 'app',
  ran_at      timestamptz not null default now(),
  summary     jsonb not null default '{}'
);
create index if not exists agent_runs_centre_idx on public.agent_runs (centre_id, ran_at desc);

-- uploaded certificates: what was extracted and what the checks found
alter table public.certificate_submissions add column if not exists file_name   text not null default '';
alter table public.certificate_submissions add column if not exists file_data   text;          -- small data URL when uploaded through a request link
alter table public.certificate_submissions add column if not exists file_hash   text;
alter table public.certificate_submissions add column if not exists extracted   jsonb not null default '{}';
alter table public.certificate_submissions add column if not exists checks      jsonb not null default '[]';
alter table public.certificate_submissions add column if not exists review_flag text not null default 'clear';
alter table public.certificate_submissions add column if not exists task_id     uuid references public.credential_tasks (id) on delete set null;
alter table public.certificate_submissions add column if not exists source      text not null default 'app';

alter table public.staff add column if not exists phone text not null default '';

-- ---------------------------------------------------------------------------
-- security: owners and directors see everything for their centre; educators see their own
-- ---------------------------------------------------------------------------
alter table public.credential_tasks enable row level security;
alter table public.agent_messages enable row level security;
alter table public.agent_events enable row level security;
alter table public.agent_runs enable row level security;
drop policy if exists "leaders read tasks" on public.credential_tasks;
create policy "leaders read tasks" on public.credential_tasks for select using (centre_id = public.my_centre_id() and public.is_leader());
drop policy if exists "educators read own tasks" on public.credential_tasks;
create policy "educators read own tasks" on public.credential_tasks for select
  using (exists (select 1 from public.staff s where s.id = staff_id and s.user_id = auth.uid()));
drop policy if exists "leaders read messages" on public.agent_messages;
create policy "leaders read messages" on public.agent_messages for select using (centre_id = public.my_centre_id() and public.is_leader());
drop policy if exists "educators read own messages" on public.agent_messages;
create policy "educators read own messages" on public.agent_messages for select
  using (exists (select 1 from public.staff s where s.id = staff_id and s.user_id = auth.uid()));
drop policy if exists "leaders read events" on public.agent_events;
create policy "leaders read events" on public.agent_events for select using (centre_id = public.my_centre_id() and public.is_leader());
drop policy if exists "leaders read runs" on public.agent_runs;
create policy "leaders read runs" on public.agent_runs for select using (centre_id = public.my_centre_id() and public.is_leader());
grant select on public.credential_tasks, public.agent_messages, public.agent_events, public.agent_runs to authenticated;

-- ---------------------------------------------------------------------------
-- helpers
-- ---------------------------------------------------------------------------
create or replace function public.cert_priority(p_days int, p_missing boolean default false)
returns text language sql immutable as $$
  select case when p_missing or p_days < 0 then 'critical'
              when p_days <= 7 then 'high'
              when p_days <= 30 then 'medium'
              else 'monitor' end;
$$;
grant execute on function public.cert_priority(int, boolean) to anon, authenticated;

create or replace function public._prio_rank(p text) returns int language sql immutable as $$
  select case p when 'critical' then 4 when 'high' then 3 when 'medium' then 2 else 1 end;
$$;

create or replace function public._follow_up_days(p text) returns int language sql immutable as $$
  select case p when 'critical' then 1 when 'high' then 2 when 'medium' then 5 else 14 end;
$$;

create or replace function public._agent_event(p_centre uuid, p_task uuid, p_staff uuid, p_type uuid, p_kind text, p_state text,
  p_summary text, p_detail jsonb default '{}')
returns void language plpgsql security definer set search_path = public as $$
begin
  insert into agent_events (centre_id, task_id, staff_id, certificate_type_id, kind, state, summary, detail)
  values (p_centre, p_task, p_staff, p_type, p_kind, p_state, p_summary, coalesce(p_detail, '{}'));
  perform log_audit(p_centre, 'agent.' || p_kind, 'credential_tasks', coalesce(p_task::text, ''),
    coalesce(p_detail, '{}') || jsonb_build_object('staff_id', p_staff, 'summary', p_summary));
end $$;
revoke execute on function public._agent_event(uuid, uuid, uuid, uuid, text, text, text, jsonb) from public, anon, authenticated;

create or replace function public._fmt_date(d date) returns text language sql immutable as $$
  select trim(to_char(d, 'FMDD Mon YYYY'));
$$;

-- Send (simulate) a renewal request, follow-up or correction request for a task.
create or replace function public._agent_send(p_task uuid, p_kind text, p_note text default '')
returns uuid language plpgsql security definer set search_path = public as $$
declare
  t credential_tasks; s staff; ct certificate_types; c centres; v_channel text; v_recipient text; v_body text; v_subject text;
  v_first text; v_deadline text; v_link text; v_next date; v_id uuid; v_owner text;
begin
  select * into t from credential_tasks where id = p_task;
  select * into s from staff where id = t.staff_id;
  select * into ct from certificate_types where id = t.certificate_type_id;
  select * into c from centres where id = t.centre_id;
  select coalesce(u.full_name, 'the centre owner') into v_owner from users u where u.centre_id = t.centre_id and u.role = 'owner' limit 1;
  v_first := split_part(s.full_name, ' ', 1);
  v_link := '/#upload/' || t.upload_token;
  v_deadline := case when t.expiry_date is null then 'as soon as possible'
                     when t.expiry_date < current_date then 'now (it expired on ' || _fmt_date(t.expiry_date) || ')'
                     else 'before ' || _fmt_date(t.expiry_date) end;
  if coalesce(s.email, '') <> '' then v_channel := 'email'; v_recipient := s.email;
  elsif coalesce(s.phone, '') <> '' then v_channel := 'sms'; v_recipient := s.phone;
  else v_channel := 'none'; v_recipient := ''; end if;
  v_subject := case p_kind when 'request' then 'Please renew your ' || ct.name
                           when 'follow_up' then 'Reminder: your ' || ct.name || ' renewal'
                           else 'Please upload your ' || ct.name || ' again' end;
  v_body := 'Hi ' || v_first || ', ' ||
    case p_kind
      when 'request' then case when t.expiry_date is null then 'we don’t have a ' || ct.name || ' on file for you.'
                               when t.expiry_date < current_date then 'your ' || ct.name || ' expired on ' || _fmt_date(t.expiry_date) || '.'
                               else 'your ' || ct.name || ' expires on ' || _fmt_date(t.expiry_date) || '.' end ||
                          ' Please upload your renewed certificate ' ||
                          case when t.expiry_date >= current_date then 'before it expires' else v_deadline end || ' using your secure link.'
      when 'follow_up' then 'we haven’t received your renewed ' || ct.name || ' yet. Please upload it ' || v_deadline || ' using your secure link.'
      else 'we couldn’t accept the certificate you uploaded' || case when p_note <> '' then ' (' || p_note || ')' else '' end ||
           '. Please upload a clear copy of your current ' || ct.name || ' using your secure link.'
    end || ' Thanks, ' || split_part(v_owner, ' ', 1) || ', ' || c.name || '.';
  v_next := current_date + _follow_up_days(t.priority);
  insert into agent_messages (centre_id, task_id, staff_id, kind, channel, recipient, subject, body, upload_link, outcome, next_follow_up)
  values (t.centre_id, t.id, t.staff_id, p_kind, v_channel, v_recipient, v_subject, v_body, v_link,
          case when v_channel = 'none' then 'no_contact' else 'simulated' end, v_next)
  returning id into v_id;
  update credential_tasks set requests_sent = requests_sent + 1, last_request_at = now(), next_follow_up = v_next,
         state = case when state = 'owner_review' then state else 'waiting' end, updated_at = now()
   where id = t.id;
  perform _agent_event(t.centre_id, t.id, t.staff_id, t.certificate_type_id,
    case p_kind when 'request' then 'request_sent' when 'follow_up' then 'follow_up_sent' else 'correction_requested' end,
    'Action taken',
    case p_kind when 'request' then 'Renewal request sent' when 'follow_up' then 'Follow-up sent' else 'Corrected upload requested' end,
    jsonb_build_object('message_id', v_id, 'channel', v_channel, 'recipient', v_recipient, 'simulated', true, 'next_follow_up', v_next));
  return v_id;
end $$;
revoke execute on function public._agent_send(uuid, text, text) from public, anon, authenticated;

create or replace function public._escalate(p_task uuid, p_reason text, p_action text)
returns void language plpgsql security definer set search_path = public as $$
declare t credential_tasks;
begin
  select * into t from credential_tasks where id = p_task;
  update credential_tasks set escalated_at = now(), escalation_reason = p_reason, recommended_action = p_action,
         escalation_ack_at = null, state = 'owner_review', updated_at = now()
   where id = p_task;
  perform _agent_event(t.centre_id, t.id, t.staff_id, t.certificate_type_id, 'escalated', 'Owner review',
    'Escalated to you', jsonb_build_object('reason', p_reason, 'recommended_action', p_action));
end $$;
revoke execute on function public._escalate(uuid, text, text) from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- the loop
-- ---------------------------------------------------------------------------
create or replace function public.run_staff_agent_for(p_centre uuid, p_trigger text default 'app')
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  r record; t credential_tasks; v_prio text; v_days int; v_reason text; v_pending boolean;
  n_detected int := 0; n_requests int := 0; n_followups int := 0; n_escalated int := 0; n_resolved int := 0; n_reprio int := 0;
  v_window int;
begin
  for r in
    select s.id as staff_id, s.full_name, s.email, s.phone, ct.id as type_id, ct.code, ct.name as type_name, ct.reminder_days,
           sc.id as cert_id, sc.expiry_date
    from staff s
    cross join certificate_types ct
    left join lateral (select x.* from staff_certificates x where x.staff_id = s.id and x.certificate_type_id = ct.id
                       order by x.expiry_date desc nulls last limit 1) sc on true
    where s.centre_id = p_centre and s.is_active and s.position not ilike '%owner%' and ct.code = any (_required_cert_codes())
  loop
    v_window := greatest(coalesce(r.reminder_days, 60), 60);
    v_days := case when r.expiry_date is null then null else r.expiry_date - current_date end;
    select * into t from credential_tasks where staff_id = r.staff_id and certificate_type_id = r.type_id and state <> 'resolved';
    v_pending := exists (select 1 from certificate_submissions cs where cs.staff_id = r.staff_id and cs.certificate_type_id = r.type_id and cs.status = 'pending');

    -- nothing to do: current beyond the reminder window
    if r.cert_id is not null and v_days > v_window then
      if t.id is not null and not v_pending then
        update credential_tasks set state = 'resolved', resolved_at = now(), resolution = 'Credential current', updated_at = now() where id = t.id;
        perform _agent_event(p_centre, t.id, r.staff_id, r.type_id, 'resolved', 'Resolved', 'Renewal complete',
          jsonb_build_object('expiry_date', r.expiry_date));
        n_resolved := n_resolved + 1;
      end if;
      continue;
    end if;

    v_prio := cert_priority(coalesce(v_days, -1), r.cert_id is null);
    v_reason := case when r.cert_id is null then 'No ' || r.type_name || ' on file'
                     when v_days < 0 then 'Expired ' || _fmt_date(r.expiry_date)
                     when v_days = 0 then 'Expires today'
                     else 'Expires in ' || v_days || ' day' || case when v_days = 1 then '' else 's' end || ' (' || _fmt_date(r.expiry_date) || ')' end;

    -- detect
    if t.id is null then
      insert into credential_tasks (centre_id, staff_id, certificate_type_id, priority, state, reason, expiry_date)
      values (p_centre, r.staff_id, r.type_id, v_prio, case when v_pending then 'owner_review' else 'monitoring' end, v_reason, r.expiry_date)
      returning * into t;
      perform _agent_event(p_centre, t.id, r.staff_id, r.type_id, 'detected', 'Monitoring',
        initcap(v_prio) || ' priority detected', jsonb_build_object('priority', v_prio, 'reason', v_reason));
      n_detected := n_detected + 1;
    else
      if _prio_rank(v_prio) > _prio_rank(t.priority) then
        perform _agent_event(p_centre, t.id, r.staff_id, r.type_id, 'reprioritised', 'Monitoring',
          'Priority raised to ' || v_prio, jsonb_build_object('from', t.priority, 'to', v_prio, 'reason', v_reason));
        n_reprio := n_reprio + 1;
        -- more urgent now: follow up today rather than waiting for the old date
        update credential_tasks set next_follow_up = least(coalesce(next_follow_up, current_date), current_date) where id = t.id and requests_sent > 0;
      end if;
      update credential_tasks set priority = v_prio, reason = v_reason, expiry_date = r.expiry_date, updated_at = now() where id = t.id;
      select * into t from credential_tasks where id = t.id;
    end if;

    -- an upload is waiting for the owner: nothing else to send
    if v_pending then
      if t.state <> 'owner_review' then update credential_tasks set state = 'owner_review', updated_at = now() where id = t.id; end if;
      continue;
    end if;

    -- act: first request for anything that is not just being monitored
    if v_prio <> 'monitor' and t.requests_sent = 0 then
      perform _agent_send(t.id, 'request');
      n_requests := n_requests + 1;
      select * into t from credential_tasks where id = t.id;
      if coalesce(r.email, '') = '' and coalesce(r.phone, '') = '' and t.escalated_at is null then
        perform _escalate(t.id, 'No email or mobile number on file, so ' || split_part(r.full_name, ' ', 1) || ' can’t be contacted.',
          'Add contact details to the staff record, or give ' || split_part(r.full_name, ' ', 1) || ' the upload link in person.');
        n_escalated := n_escalated + 1;
      end if;
    -- follow up when the date passes with no upload
    elsif t.requests_sent > 0 and t.next_follow_up is not null and t.next_follow_up <= current_date and t.state <> 'resolved' then
      perform _agent_send(t.id, 'follow_up');
      n_followups := n_followups + 1;
      select * into t from credential_tasks where id = t.id;
    end if;

    -- escalate what needs the owner's judgement
    if t.escalated_at is null then
      if v_prio = 'critical' then
        perform _escalate(t.id,
          case when r.cert_id is null then split_part(r.full_name, ' ', 1) || ' has no ' || r.type_name || ' on file.'
               else split_part(r.full_name, ' ', 1) || '''s ' || r.type_name || ' expired on ' || _fmt_date(r.expiry_date) || '.' end,
          case r.code
            when 'WWCC' then 'Stop ' || split_part(r.full_name, ' ', 1) || ' working with children until a current Check is verified with the Office of the Children’s Guardian.'
            when 'FIRST_AID' then 'Don’t count ' || split_part(r.full_name, ' ', 1) || ' towards first aid cover (Reg. 136). Check the roster has another qualified educator on every shift.'
            when 'CPR' then 'Don’t count ' || split_part(r.full_name, ' ', 1) || ' towards first aid cover until CPR is renewed. Check the roster.'
            else 'Make sure another educator with current anaphylaxis training is on every shift until ' || split_part(r.full_name, ' ', 1) || ' renews.' end);
        n_escalated := n_escalated + 1;
      elsif t.requests_sent >= 3 then
        perform _escalate(t.id, split_part(r.full_name, ' ', 1) || ' hasn’t responded to ' || t.requests_sent || ' requests.',
          'Speak to ' || split_part(r.full_name, ' ', 1) || ' directly and agree a date to renew.');
        n_escalated := n_escalated + 1;
      end if;
    end if;
    -- after the owner acknowledges an escalation, the task goes back to waiting
    select * into t from credential_tasks where id = t.id;
    if t.state = 'owner_review' and t.escalation_ack_at is not null then
      update credential_tasks set state = case when t.requests_sent > 0 then 'waiting' else 'monitoring' end where id = t.id;
    elsif t.state = 'monitoring' and t.requests_sent > 0 then
      update credential_tasks set state = 'waiting' where id = t.id;
    end if;
  end loop;

  insert into agent_runs (centre_id, trigger, summary) values (p_centre, p_trigger, jsonb_build_object(
    'detected', n_detected, 'requests', n_requests, 'follow_ups', n_followups, 'escalated', n_escalated, 'resolved', n_resolved, 'reprioritised', n_reprio));
  return jsonb_build_object('detected', n_detected, 'requests', n_requests, 'follow_ups', n_followups,
                            'escalated', n_escalated, 'resolved', n_resolved, 'reprioritised', n_reprio, 'ran_at', now());
end $$;
revoke execute on function public.run_staff_agent_for(uuid, text) from public, anon, authenticated;

-- The app calls this when the owner opens beehive (and from "Check now").
create or replace function public.run_staff_agent()
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_leader() then raise exception 'Only the owner or director can run the agent'; end if;
  return run_staff_agent_for(my_centre_id(), 'app');
end $$;
grant execute on function public.run_staff_agent() to authenticated;

-- Scheduled run for every centre (pg_cron, below).
create or replace function public.run_staff_agent_all()
returns int language plpgsql security definer set search_path = public as $$
declare c record; n int := 0;
begin
  for c in select id from centres loop perform run_staff_agent_for(c.id, 'schedule'); n := n + 1; end loop;
  return n;
end $$;
revoke execute on function public.run_staff_agent_all() from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- certificate uploads: extraction results are checked against the record
-- ---------------------------------------------------------------------------
create or replace function public._norm(p text) returns text language sql immutable as $$
  select trim(regexp_replace(lower(coalesce(p, '')), '[^a-z ]+', ' ', 'g'));
$$;

create or replace function public._submit_checked(p_staff staff, p_type certificate_types, p_file_name text, p_file_data text,
  p_file_path text, p_file_hash text, p_extracted jsonb, p_expiry date, p_issue date, p_source text, p_submitted_by uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_checks jsonb := '[]'; v_flag text := 'clear'; v_ext jsonb := coalesce(p_extracted, '{}'); v_cur date; v_dup record;
  v_ex_name text; v_ex_type text; v_ex_expiry date; v_ex_issue date; v_task credential_tasks; v_id uuid; v_old uuid; v_readable boolean;
  v_tok text; v_ok boolean;
begin
  if p_expiry is not null and p_expiry < current_date then raise exception 'That expiry date has already passed'; end if;
  -- the same file twice: tell the uploader instead of creating a second record
  if coalesce(p_file_hash, '') <> '' then
    select cs.id, cs.status, cs.submitted_at into v_dup from certificate_submissions cs
     where cs.staff_id = p_staff.id and cs.file_hash = p_file_hash and cs.status in ('pending', 'approved')
     order by cs.submitted_at desc limit 1;
    if v_dup.id is not null then
      raise exception 'This file was already uploaded on % and is %.', _fmt_date(v_dup.submitted_at::date),
        case when v_dup.status = 'pending' then 'waiting for the centre to check it' else 'already approved' end;
    end if;
  end if;

  v_readable := coalesce((v_ext->>'readable')::boolean, false);
  v_ex_name := nullif(v_ext->>'name', '');
  v_ex_type := nullif(v_ext->>'type_code', '');
  v_ex_expiry := nullif(v_ext->>'expiry_date', '')::date;
  v_ex_issue := nullif(v_ext->>'issue_date', '')::date;
  select max(expiry_date) into v_cur from staff_certificates where staff_id = p_staff.id and certificate_type_id = p_type.id;

  if not v_readable then
    v_checks := v_checks || jsonb_build_object('field', 'document', 'issue', 'unreadable',
      'message', 'beehive couldn’t read any text on this file. Check it’s a clear photo or PDF of the right certificate.');
  else
    if v_ex_name is null then
      v_checks := v_checks || jsonb_build_object('field', 'name', 'issue', 'missing', 'message', 'No name found on the certificate.');
    else
      v_ok := true;
      foreach v_tok in array string_to_array(_norm(p_staff.full_name), ' ') loop
        if v_tok <> '' and position(v_tok in _norm(v_ex_name)) = 0 then v_ok := false; end if;
      end loop;
      if not v_ok then
        v_checks := v_checks || jsonb_build_object('field', 'name', 'issue', 'mismatch',
          'message', 'The name on the certificate (' || v_ex_name || ') doesn’t match ' || p_staff.full_name || '.');
      end if;
    end if;
    if v_ex_type is null then
      v_checks := v_checks || jsonb_build_object('field', 'type', 'issue', 'missing', 'message', 'Couldn’t tell which credential this is.');
    elsif v_ex_type <> p_type.code then
      v_checks := v_checks || jsonb_build_object('field', 'type', 'issue', 'mismatch',
        'message', 'This looks like a ' || coalesce((select name from certificate_types where code = v_ex_type), v_ex_type) || ', not a ' || p_type.name || '.');
    end if;
    if v_ex_expiry is null then
      v_checks := v_checks || jsonb_build_object('field', 'expiry_date', 'issue', 'missing', 'message', 'No expiry date found on the certificate.');
    else
      if v_ex_expiry < current_date then
        v_checks := v_checks || jsonb_build_object('field', 'expiry_date', 'issue', 'expired', 'message', 'The certificate expired on ' || _fmt_date(v_ex_expiry) || '.');
      elsif v_cur is not null and v_ex_expiry <= v_cur then
        v_checks := v_checks || jsonb_build_object('field', 'expiry_date', 'issue', 'not_newer',
          'message', 'The expiry date (' || _fmt_date(v_ex_expiry) || ') isn’t later than the one on file (' || _fmt_date(v_cur) || '). This may be the old certificate.');
      end if;
      if p_expiry is not null and p_expiry <> v_ex_expiry then
        v_checks := v_checks || jsonb_build_object('field', 'expiry_date', 'issue', 'differs',
          'message', 'The date entered (' || _fmt_date(p_expiry) || ') differs from the date read from the certificate (' || _fmt_date(v_ex_expiry) || ').');
      end if;
    end if;
    if v_ex_issue is not null and v_ex_issue > (now() at time zone 'Australia/Sydney')::date then
      v_checks := v_checks || jsonb_build_object('field', 'issue_date', 'issue', 'future', 'message', 'The issue date is in the future.');
    end if;
  end if;
  -- anything the reader itself was unsure about
  if jsonb_typeof(v_ext->'uncertain') = 'array' then
    select v_checks || coalesce(jsonb_agg(jsonb_build_object('field', 'document', 'issue', 'uncertain', 'message', u)), '[]')
      into v_checks from jsonb_array_elements_text(v_ext->'uncertain') u;
  end if;
  v_flag := case when not v_readable then 'unreadable' when jsonb_array_length(v_checks) > 0 then 'needs_check' else 'clear' end;

  -- a newer upload replaces an older one that hasn't been checked yet
  for v_old in select id from certificate_submissions where staff_id = p_staff.id and certificate_type_id = p_type.id and status = 'pending' loop
    update certificate_submissions set status = 'rejected', review_note = 'Replaced by a newer upload', reviewed_at = now() where id = v_old;
  end loop;

  select * into v_task from credential_tasks where staff_id = p_staff.id and certificate_type_id = p_type.id and state <> 'resolved';
  if v_task.id is null then
    insert into credential_tasks (centre_id, staff_id, certificate_type_id, priority, state, reason, expiry_date)
    values (p_staff.centre_id, p_staff.id, p_type.id,
            cert_priority(coalesce(v_cur - current_date, -1), v_cur is null), 'owner_review', 'Renewal uploaded', v_cur)
    returning * into v_task;
  else
    update credential_tasks set state = 'owner_review', updated_at = now() where id = v_task.id;
  end if;

  insert into certificate_submissions (centre_id, staff_id, certificate_type_id, file_path, file_name, file_data, file_hash,
    certificate_number, issue_date, expiry_date, extracted_by_ai, extracted, checks, review_flag, task_id, source, submitted_by)
  values (p_staff.centre_id, p_staff.id, p_type.id, p_file_path, coalesce(p_file_name, ''), p_file_data, p_file_hash,
    coalesce(v_ext->>'number', ''), coalesce(p_issue, v_ex_issue), coalesce(p_expiry, v_ex_expiry), v_readable, v_ext, v_checks, v_flag,
    v_task.id, p_source, p_submitted_by)
  returning id into v_id;

  perform _agent_event(p_staff.centre_id, v_task.id, p_staff.id, p_type.id, 'upload_received', 'Owner review', 'Certificate uploaded',
    jsonb_build_object('submission_id', v_id, 'source', p_source, 'file_name', p_file_name, 'extracted_expiry', v_ex_expiry));
  if v_flag <> 'clear' then
    perform _agent_event(p_staff.centre_id, v_task.id, p_staff.id, p_type.id, 'flagged', 'Owner review',
      case when v_flag = 'unreadable' then 'Upload unreadable: needs checking' else 'Upload needs checking' end,
      jsonb_build_object('submission_id', v_id, 'checks', v_checks));
  else
    perform _agent_event(p_staff.centre_id, v_task.id, p_staff.id, p_type.id, 'flagged', 'Owner review', 'Ready for your verification',
      jsonb_build_object('submission_id', v_id, 'checks', v_checks));
  end if;
  return jsonb_build_object('id', v_id, 'flag', v_flag, 'checks', v_checks);
end $$;
revoke execute on function public._submit_checked(staff, certificate_types, text, text, text, text, jsonb, date, date, text, uuid) from public, anon, authenticated;

-- Signed-in upload (educator for themselves, owner/director on someone's behalf).
create or replace function public.submit_certificate_checked(p_type_code text, p_file_name text, p_file_path text default null,
  p_file_data text default null, p_file_hash text default null, p_extracted jsonb default '{}', p_expiry date default null,
  p_issue date default null, p_staff_id uuid default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_staff staff; v_type certificate_types;
begin
  if p_staff_id is not null and is_leader() then
    select * into v_staff from staff where id = p_staff_id and centre_id = my_centre_id() and is_active;
  else
    select * into v_staff from staff where user_id = auth.uid() and is_active;
  end if;
  if v_staff.id is null then raise exception 'Staff record not found. Ask the director to add you to the staff register.'; end if;
  select * into v_type from certificate_types where code = upper(replace(trim(p_type_code), ' ', '_'));
  if v_type.id is null then raise exception 'Unknown certificate type %', p_type_code; end if;
  if p_file_data is not null and length(p_file_data) > 4000000 then raise exception 'That file is too large. Use a photo under 3 MB.'; end if;
  return _submit_checked(v_staff, v_type, p_file_name, p_file_data, p_file_path, p_file_hash, p_extracted, p_expiry, p_issue,
    case when p_staff_id is not null and is_leader() then 'owner' else 'educator' end, auth.uid());
end $$;
grant execute on function public.submit_certificate_checked(text, text, text, text, text, jsonb, date, date, uuid) to authenticated;

-- What the secure upload link shows (no sign-in needed).
create or replace function public.upload_request_info(p_token uuid)
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object('first_name', split_part(s.full_name, ' ', 1), 'full_name', s.full_name, 'centre', c.name,
           'credential', ct.name, 'type_code', ct.code, 'expiry_date', t.expiry_date, 'state', t.state,
           'pending', exists (select 1 from certificate_submissions cs where cs.task_id = t.id and cs.status = 'pending'))
  from credential_tasks t join staff s on s.id = t.staff_id join centres c on c.id = t.centre_id
  join certificate_types ct on ct.id = t.certificate_type_id
  where t.upload_token = p_token and t.state <> 'resolved';
$$;
grant execute on function public.upload_request_info(uuid) to anon, authenticated;

create or replace function public.submit_certificate_by_token(p_token uuid, p_file_name text, p_file_data text,
  p_file_hash text default null, p_extracted jsonb default '{}', p_expiry date default null, p_issue date default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare t credential_tasks; v_staff staff; v_type certificate_types;
begin
  select * into t from credential_tasks where upload_token = p_token and state <> 'resolved';
  if t.id is null then raise exception 'This upload link has expired or the renewal is already complete.'; end if;
  if coalesce(p_file_data, '') = '' then raise exception 'Choose a photo or PDF of your certificate.'; end if;
  if length(p_file_data) > 4000000 then raise exception 'That file is too large. Use a photo under 3 MB.'; end if;
  select * into v_staff from staff where id = t.staff_id;
  select * into v_type from certificate_types where id = t.certificate_type_id;
  return _submit_checked(v_staff, v_type, p_file_name, p_file_data, null, p_file_hash, p_extracted, p_expiry, p_issue, 'link', null);
end $$;
grant execute on function public.submit_certificate_by_token(uuid, text, text, text, jsonb, date, date) to anon, authenticated;

-- Owner decision on an upload.
create or replace function public.verify_certificate(p_submission uuid, p_approve boolean, p_expiry date default null, p_reason text default '')
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_sub certificate_submissions; v_cert uuid; v_expiry date; v_task credential_tasks; v_type certificate_types;
begin
  if not is_leader() then raise exception 'Only the owner or director can verify certificates'; end if;
  select * into v_sub from certificate_submissions where id = p_submission and centre_id = my_centre_id() for update;
  if not found then raise exception 'Submission not found'; end if;
  if v_sub.status <> 'pending' then raise exception 'This upload has already been %.', case when v_sub.status = 'approved' then 'approved' else 'rejected or replaced' end; end if;
  select * into v_type from certificate_types where id = v_sub.certificate_type_id;
  select * into v_task from credential_tasks where id = v_sub.task_id;
  if v_task.id is null then
    select * into v_task from credential_tasks where staff_id = v_sub.staff_id and certificate_type_id = v_sub.certificate_type_id and state <> 'resolved';
  end if;

  if p_approve then
    v_expiry := coalesce(p_expiry, v_sub.expiry_date);
    if v_expiry is null then raise exception 'Enter the expiry date before approving.'; end if;
    if v_expiry < current_date then raise exception 'That expiry date has already passed, so the certificate can’t be approved.'; end if;
    select id into v_cert from staff_certificates where staff_id = v_sub.staff_id and certificate_type_id = v_sub.certificate_type_id
      order by expiry_date desc nulls last limit 1;
    if v_cert is null then
      insert into staff_certificates (staff_id, certificate_type_id, certificate_number, issue_date, expiry_date, document_url)
      values (v_sub.staff_id, v_sub.certificate_type_id, v_sub.certificate_number, v_sub.issue_date, v_expiry, v_sub.file_path)
      returning id into v_cert;
    else
      update staff_certificates set expiry_date = v_expiry, issue_date = coalesce(v_sub.issue_date, issue_date),
        certificate_number = coalesce(nullif(v_sub.certificate_number, ''), certificate_number),
        document_url = coalesce(v_sub.file_path, document_url)
      where id = v_cert;
    end if;
    update certificate_submissions set status = 'approved', expiry_date = v_expiry, reviewed_by = auth.uid(), reviewed_at = now(),
      review_note = coalesce(p_reason, '') where id = p_submission;
    perform log_audit(v_sub.centre_id, 'certificate.approved', 'certificate_submissions', p_submission::text,
      jsonb_build_object('staff_certificate_id', v_cert, 'expiry_date', v_expiry, 'staff_id', v_sub.staff_id));
    if v_task.id is not null then
      perform _agent_event(v_sub.centre_id, v_task.id, v_sub.staff_id, v_sub.certificate_type_id, 'approved', 'Resolved',
        'Certificate verified', jsonb_build_object('submission_id', p_submission, 'expiry_date', v_expiry));
      perform _agent_event(v_sub.centre_id, v_task.id, v_sub.staff_id, v_sub.certificate_type_id, 'record_updated', 'Resolved',
        'Staff record updated', jsonb_build_object('expiry_date', v_expiry, 'verified_at', now()));
      update credential_tasks set state = 'resolved', resolved_at = now(), resolution = 'Renewed until ' || _fmt_date(v_expiry),
        expiry_date = v_expiry, updated_at = now() where id = v_task.id;
      perform _agent_event(v_sub.centre_id, v_task.id, v_sub.staff_id, v_sub.certificate_type_id, 'resolved', 'Resolved',
        'Renewal task closed', jsonb_build_object('expiry_date', v_expiry));
    end if;
    return jsonb_build_object('approved', true, 'expiry_date', v_expiry);
  else
    if coalesce(trim(p_reason), '') = '' then raise exception 'Say why the upload is being rejected, so the educator knows what to fix.'; end if;
    update certificate_submissions set status = 'rejected', reviewed_by = auth.uid(), reviewed_at = now(), review_note = p_reason
     where id = p_submission;
    perform log_audit(v_sub.centre_id, 'certificate.rejected', 'certificate_submissions', p_submission::text,
      jsonb_build_object('reason', p_reason, 'staff_id', v_sub.staff_id));
    if v_task.id is not null then
      update credential_tasks set state = 'waiting', updated_at = now() where id = v_task.id;
      perform _agent_event(v_sub.centre_id, v_task.id, v_sub.staff_id, v_sub.certificate_type_id, 'rejected', 'Action taken',
        'Upload rejected', jsonb_build_object('submission_id', p_submission, 'reason', p_reason));
      perform _agent_send(v_task.id, 'correction', p_reason);
    end if;
    return jsonb_build_object('approved', false);
  end if;
end $$;
grant execute on function public.verify_certificate(uuid, boolean, date, text) to authenticated;

-- Owner acknowledges an escalation (the agent keeps chasing the renewal).
create or replace function public.acknowledge_escalation(p_task uuid, p_note text default '')
returns void language plpgsql security definer set search_path = public as $$
declare t credential_tasks;
begin
  if not is_leader() then raise exception 'Only the owner or director can do this'; end if;
  select * into t from credential_tasks where id = p_task and centre_id = my_centre_id();
  if not found then raise exception 'Task not found'; end if;
  if t.escalated_at is null or t.escalation_ack_at is not null then raise exception 'There’s nothing to acknowledge on this task.'; end if;
  update credential_tasks set escalation_ack_at = now(),
    state = case when exists (select 1 from certificate_submissions cs where cs.task_id = t.id and cs.status = 'pending') then 'owner_review'
                 when requests_sent > 0 then 'waiting' else 'monitoring' end,
    updated_at = now() where id = p_task;
  perform _agent_event(t.centre_id, t.id, t.staff_id, t.certificate_type_id, 'escalation_acknowledged', 'Waiting',
    'You acknowledged the escalation', jsonb_build_object('note', coalesce(p_note, '')));
end $$;
grant execute on function public.acknowledge_escalation(uuid, text) to authenticated;

-- Owner asks the agent to chase now instead of waiting for the follow-up date.
create or replace function public.agent_send_now(p_task uuid)
returns uuid language plpgsql security definer set search_path = public as $$
declare t credential_tasks;
begin
  if not is_leader() then raise exception 'Only the owner or director can do this'; end if;
  select * into t from credential_tasks where id = p_task and centre_id = my_centre_id();
  if not found or t.state = 'resolved' then raise exception 'This renewal is already complete.'; end if;
  return _agent_send(t.id, case when t.requests_sent = 0 then 'request' else 'follow_up' end);
end $$;
grant execute on function public.agent_send_now(uuid) to authenticated;

-- ---------------------------------------------------------------------------
-- views for the interface
-- ---------------------------------------------------------------------------
create or replace view public.v_credential_tasks with (security_invoker = on) as
select t.*, s.full_name as staff_name, coalesce(nullif(s.room, ''), '—') as room, s.email, s.phone, s.user_id as staff_user_id,
       ct.code as type_code, ct.name as type_name,
       case when t.expiry_date is null then null else t.expiry_date - current_date end as days_left,
       lm.sent_at as last_message_at, lm.channel as last_channel, lm.kind as last_kind, lm.recipient as last_recipient,
       ps.id as pending_submission_id, ps.review_flag as pending_flag
from public.credential_tasks t
join public.staff s on s.id = t.staff_id
join public.certificate_types ct on ct.id = t.certificate_type_id
left join lateral (select m.* from public.agent_messages m where m.task_id = t.id order by m.sent_at desc limit 1) lm on true
left join lateral (select cs.id, cs.review_flag from public.certificate_submissions cs where cs.task_id = t.id and cs.status = 'pending'
                   order by cs.submitted_at desc limit 1) ps on true;
grant select on public.v_credential_tasks to authenticated;

drop view if exists public.v_agent_feed;  -- later migrations add columns; recreate so this file can be re-run
create view public.v_agent_feed with (security_invoker = on) as
select e.id, e.centre_id, e.task_id, e.staff_id, e.kind, e.state, e.summary, e.detail, e.demo, e.created_at,
       s.full_name as staff_name, ct.code as type_code, ct.name as type_name,
       t.state as task_state, t.priority as task_priority, t.next_follow_up
from public.agent_events e
left join public.staff s on s.id = e.staff_id
left join public.certificate_types ct on ct.id = e.certificate_type_id
left join public.credential_tasks t on t.id = e.task_id;
grant select on public.v_agent_feed to authenticated;

-- ---------------------------------------------------------------------------
-- schedule: run every morning at 7:00 Sydney time where pg_cron is available
-- ---------------------------------------------------------------------------
do $$
begin
  begin
    create extension if not exists pg_cron;
  exception when others then
    raise notice 'pg_cron not available: the agent will run when the owner opens beehive';
  end;
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    begin
      perform cron.unschedule('beehive-staff-agent') where exists (select 1 from cron.job where jobname = 'beehive-staff-agent');
      perform cron.schedule('beehive-staff-agent', '0 20 * * *', 'select public.run_staff_agent_all()');  -- 20:00 UTC = 7:00 AEDT
    exception when others then
      raise notice 'Could not schedule the staff agent: %', sqlerrm;
    end;
  end if;
end $$;

-- ============================================================================
-- supabase/migrations/20261029090000_audit_agent.sql
-- ============================================================================
-- beehive audit-readiness agent
-- Watches every requirement in the approved checklist and its evidence, explains each gap, coordinates the
-- follow-up and recalculates readiness as gaps close. It reuses the staff agent's credential workflow for the
-- staff-record requirements and writes to the same activity feed (agent_events, agent = 'audit').
--
-- Requirement status: missing, under_review, compliant. Indicators: overdue, review_due, review_required,
-- awaiting_verification, expiring, task_overdue. An upload never makes a requirement compliant by itself:
-- uploaded evidence is 'pending' until the owner verifies it.
-- Readiness = (compliant x 1 + under review x 0.5 + missing x 0) / approved requirements.

-- ---------------------------------------------------------------------------
-- evidence now carries a verification state and the agent's assessment
-- ---------------------------------------------------------------------------
-- Evidence recorded before this migration was accepted under the old rules, so it starts as verified.
do $$ begin
  if not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'evidence' and column_name = 'status') then
    alter table public.evidence add column status text not null default 'verified';
    alter table public.evidence alter column status set default 'pending';
  end if;
end $$;
alter table public.evidence add column if not exists verified_by uuid references public.users (id) on delete set null;
alter table public.evidence add column if not exists verified_at timestamptz;
alter table public.evidence add column if not exists review_note text not null default '';
alter table public.evidence add column if not exists file_name text not null default '';
alter table public.evidence add column if not exists file_data text;
alter table public.evidence add column if not exists file_hash text;
alter table public.evidence add column if not exists extracted jsonb not null default '{}';
alter table public.evidence add column if not exists checks jsonb not null default '[]';
alter table public.evidence add column if not exists review_flag text not null default 'clear';
alter table public.evidence add column if not exists source text not null default 'app';
alter table public.evidence add column if not exists details jsonb not null default '{}';
do $$ begin
  alter table public.evidence add constraint evidence_status_check check (status in ('pending', 'verified', 'rejected', 'superseded'));
exception when duplicate_object then null; end $$;
update public.evidence set verified_at = created_at, verified_by = uploaded_by where status = 'verified' and verified_at is null;

alter table public.checklist_items add column if not exists agent_status text;
alter table public.checklist_items add column if not exists agent_priority text;
alter table public.checklist_items add column if not exists last_reviewed_at timestamptz;
alter table public.checklist_items add column if not exists reviewed_by uuid references public.users (id) on delete set null;

-- regulation updates gain an "assessed" step between new and reviewed
do $$
declare c text;
begin
  select conname into c from pg_constraint where conrelid = 'public.regulation_updates'::regclass and contype = 'c' and pg_get_constraintdef(oid) ilike '%status%';
  if c is not null then execute 'alter table public.regulation_updates drop constraint ' || quote_ident(c); end if;
  alter table public.regulation_updates add constraint regulation_updates_status_check check (status in ('new', 'assessed', 'accepted', 'reviewed'));
end $$;
alter table public.regulation_updates add column if not exists assessed_at timestamptz;
alter table public.regulation_updates add column if not exists assessment text not null default '';

-- ---------------------------------------------------------------------------
-- tables
-- ---------------------------------------------------------------------------
create table if not exists public.audit_tasks (
  id                    uuid primary key default gen_random_uuid(),
  centre_id             uuid not null references public.centres (id) on delete cascade,
  checklist_item_id     uuid references public.checklist_items (id) on delete cascade,
  kind                  text not null check (kind in ('evidence', 'regulation_review', 'overdue_task', 'owner_action')),
  title                 text not null,
  reason                text not null default '',
  recommended_action    text not null default '',
  priority              text not null default 'medium' check (priority in ('critical', 'high', 'medium', 'low')),
  state                 text not null default 'waiting' check (state in ('monitoring', 'waiting', 'owner_review', 'resolved')),
  assignee_staff_id     uuid references public.staff (id) on delete set null,   -- null = the owner
  due_date              date,
  next_follow_up        date,
  requests_sent         int not null default 0,
  last_request_at       timestamptz,
  escalated_at          timestamptz,
  evidence_id           uuid references public.evidence (id) on delete set null,
  regulation_update_id  uuid references public.regulation_updates (id) on delete cascade,
  compliance_record_id  uuid references public.compliance_records (id) on delete cascade,
  upload_token          uuid not null default gen_random_uuid(),
  opened_at             timestamptz not null default now(),
  updated_at            timestamptz not null default now(),
  resolved_at           timestamptz,
  resolution            text
);
create unique index if not exists audit_tasks_open_evidence on public.audit_tasks (checklist_item_id, kind) where state <> 'resolved' and kind in ('evidence', 'owner_action');
create unique index if not exists audit_tasks_open_reg on public.audit_tasks (regulation_update_id, checklist_item_id) where state <> 'resolved' and kind = 'regulation_review';
create unique index if not exists audit_tasks_open_record on public.audit_tasks (compliance_record_id) where state <> 'resolved' and kind = 'overdue_task';
create unique index if not exists audit_tasks_token on public.audit_tasks (upload_token);
create index if not exists audit_tasks_centre on public.audit_tasks (centre_id, state);

create table if not exists public.regulation_reviews (
  id                    uuid primary key default gen_random_uuid(),
  centre_id             uuid not null references public.centres (id) on delete cascade,
  regulation_update_id  uuid not null references public.regulation_updates (id) on delete cascade,
  checklist_item_id     uuid references public.checklist_items (id) on delete cascade,  -- null: unclear which item
  impact                text not null check (impact in ('likely', 'possible', 'unclear')),
  reason                text not null,
  recommended           text not null,
  decision              text check (decision in ('no_change', 'update_needed', 'not_applicable')),
  note                  text not null default '',
  decided_by            uuid references public.users (id) on delete set null,
  decided_at            timestamptz,
  completed_at          timestamptz,     -- update_needed: when the updated evidence was verified
  created_at            timestamptz not null default now()
);
create unique index if not exists regulation_reviews_unique on public.regulation_reviews (regulation_update_id, coalesce(checklist_item_id, '00000000-0000-0000-0000-000000000000'::uuid));

alter table public.agent_events add column if not exists agent text not null default 'staff';
alter table public.agent_events add column if not exists checklist_item_id uuid references public.checklist_items (id) on delete cascade;
alter table public.agent_events add column if not exists audit_task_id uuid references public.audit_tasks (id) on delete cascade;
alter table public.agent_events add column if not exists regulation_update_id uuid references public.regulation_updates (id) on delete cascade;
alter table public.agent_messages add column if not exists audit_task_id uuid references public.audit_tasks (id) on delete cascade;
alter table public.agent_runs add column if not exists agent text not null default 'staff';

alter table public.audit_tasks enable row level security;
alter table public.regulation_reviews enable row level security;
drop policy if exists "leaders read audit tasks" on public.audit_tasks;
create policy "leaders read audit tasks" on public.audit_tasks for select using (centre_id = public.my_centre_id() and public.is_leader());
drop policy if exists "assignees read audit tasks" on public.audit_tasks;
create policy "assignees read audit tasks" on public.audit_tasks for select
  using (exists (select 1 from public.staff s where s.id = assignee_staff_id and s.user_id = auth.uid()));
drop policy if exists "leaders read regulation reviews" on public.regulation_reviews;
create policy "leaders read regulation reviews" on public.regulation_reviews for select using (centre_id = public.my_centre_id() and public.is_leader());
grant select on public.audit_tasks, public.regulation_reviews to authenticated;

-- ---------------------------------------------------------------------------
-- knowledge about each requirement
-- ---------------------------------------------------------------------------
-- The centre's own date (NSW). The database clock is UTC, so "today" in Sydney can be a day ahead of current_date.
create or replace function public._local_today() returns date language sql stable as $$
  select (now() at time zone 'Australia/Sydney')::date;
$$;

create or replace function public._item_task_pattern(p_key text) returns text language sql immutable as $$
  select case p_key when 'evacuation' then 'evacuat|rehears' when 'premises' then 'playground|premises' when 'sun' then 'sun protection'
                    when 'sleep' then 'sleep' when 'medical' then 'medical conditions' else null end;
$$;
create or replace function public._item_critical(p_key text) returns boolean language sql immutable as $$
  select p_key in ('wwcc', 'firstaid', 'evacuation', 'emergency', 'medical', 'incidents');
$$;
create or replace function public._item_why(p_key text) returns text language sql immutable as $$
  select case p_key
    when 'wwcc' then 'Every educator must hold a current Working with Children Check, and an officer can ask to see the register (Reg. 145–146).'
    when 'firstaid' then 'An educator with current first aid, CPR and anaphylaxis training must be on site at all times (Reg. 136).'
    when 'training' then 'Staff records must show each educator’s qualifications and training (Reg. 145–147).'
    when 'enrolment' then 'Staff must be able to reach a parent or emergency contact for every child (Reg. 160–162).'
    when 'incidents' then 'Parents must be told within 24 hours, and serious incidents notified to the regulator (Reg. 86–87).'
    when 'medical' then 'Children with medical conditions need current plans so staff can respond safely (Reg. 90–91).'
    when 'authorisations' then 'Children may only leave with an authorised person, and outings need written authorisation (Reg. 99–102).'
    when 'evacuation' then 'Emergency and evacuation procedures must be rehearsed every 3 months and each rehearsal recorded (Reg. 97).'
    when 'premises' then 'Premises, furniture and equipment must be safe, clean and well maintained (Reg. 103).'
    when 'emergency' then 'Emergency procedures, contacts and the evacuation floor plan must be current and displayed (Reg. 97, 168).'
    when 'sun' then 'The service must have a current sun protection policy that staff follow (Reg. 114, 168).'
    when 'sleep' then 'Sleep and rest policies must reflect current requirements, with a risk assessment at least every 12 months (Reg. 84A–84C).'
    else 'An authorised officer can ask to see this evidence at a visit.' end;
$$;
create or replace function public._req_label(p text) returns text language sql immutable as $$
  select case p when 'missing' then 'Missing' when 'under_review' then 'Under review' when 'compliant' then 'Compliant' else coalesce(p, '') end;
$$;
create or replace function public._audit_follow_days(p text) returns int language sql immutable as $$
  select case p when 'critical' then 2 when 'high' then 3 when 'medium' then 7 else 14 end;
$$;
create or replace function public._item_default_assignee(p_item checklist_items) returns uuid language sql stable security definer set search_path = public as $$
  select case when p_item.item_key in ('evacuation', 'premises') then
    (select s.id from staff s where s.centre_id = p_item.centre_id and s.is_active and s.position ilike 'lead%' order by s.full_name limit 1) end;
$$;

-- ---------------------------------------------------------------------------
-- the status of one requirement, with its reasons (used by the view and the agent)
-- ---------------------------------------------------------------------------
create or replace function public._requirement_status(p_item uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  ci checklist_items; v_status text; v_flags text[] := '{}'; v_reason text := ''; v_cur text := ''; v_last timestamptz;
  v_ev evidence; v_pend evidence; v_exp date; v_prio text; v_prio_reason text; v_next text := ''; v_window int;
  n_bad int := 0; n_pend int := 0; n_soon int := 0; n_total int := 0; v_names text; v_task audit_tasks; v_rev record; v_rec record; v_pat text;
  v_assignee text;
begin
  select * into ci from checklist_items where id = p_item;
  if ci.id is null then return null; end if;
  -- a signed-in user only sees their own centre
  if auth.uid() is not null and ci.centre_id is distinct from my_centre_id() then return null; end if;

  if ci.evidence_kind = 'document' then
    select * into v_ev from evidence where checklist_item_id = ci.id and status = 'verified' order by recorded_on desc, created_at desc limit 1;
    select * into v_pend from evidence where checklist_item_id = ci.id and status = 'pending' order by created_at desc limit 1;
    v_window := least(30, greatest(5, ci.review_months * 7));
    if v_ev.id is not null then v_exp := (v_ev.recorded_on + make_interval(months => ci.review_months))::date; end if;
    if v_ev.id is not null and v_exp >= current_date then
      v_status := 'compliant';
      v_cur := v_ev.title || ' (' || _fmt_date(v_ev.recorded_on) || '), verified';
      v_reason := 'Verified evidence on file, current until ' || _fmt_date(v_exp) || '.';
      if v_exp <= current_date + v_window then
        v_flags := v_flags || 'review_due'::text;
        v_reason := 'Current, but due for renewal by ' || _fmt_date(v_exp) || '.';
      end if;
      if v_pend.id is not null then v_flags := v_flags || 'awaiting_verification'::text; end if;
    elsif v_pend.id is not null then
      v_status := 'under_review';
      v_cur := v_pend.title || ', uploaded ' || _fmt_date(v_pend.created_at::date) || ', not yet verified';
      v_reason := 'New evidence uploaded and waiting for verification.' ||
                  case when v_ev.id is not null then ' The last verified evidence expired on ' || _fmt_date(v_exp) || '.' else '' end;
      v_flags := v_flags || 'awaiting_verification'::text;
      if v_ev.id is not null then v_flags := v_flags || 'overdue'::text; end if;
    else
      v_status := 'missing';
      if v_ev.id is not null then
        v_flags := v_flags || 'overdue'::text;
        v_cur := v_ev.title || ' (' || _fmt_date(v_ev.recorded_on) || '), expired ' || _fmt_date(v_exp);
        v_reason := 'Out of date: the last verified evidence is from ' || _fmt_date(v_ev.recorded_on) || ' and expired on ' || _fmt_date(v_exp) || '.';
      else
        v_cur := 'No evidence on file';
        v_reason := 'No verified evidence on file.';
      end if;
    end if;
    v_last := coalesce(v_ev.verified_at, v_ev.created_at);

  elsif ci.evidence_kind = 'certificates' then
    with req as (
      select s.id sid, s.full_name, ct.id tid, ct.name tname from staff s cross join certificate_types ct
      where s.centre_id = ci.centre_id and s.is_active and s.position not ilike '%owner%' and ct.code = any (ci.cert_codes) and ct.code = any (_required_cert_codes())
    ), st as (
      select r.*, (select max(sc.expiry_date) from staff_certificates sc where sc.staff_id = r.sid and sc.certificate_type_id = r.tid) as exp,
             exists (select 1 from certificate_submissions cs where cs.staff_id = r.sid and cs.certificate_type_id = r.tid and cs.status = 'pending') as pend
      from req r
    )
    select count(*) filter (where (exp is null or exp < current_date) and not pend),
           count(*) filter (where pend),
           count(*) filter (where exp >= current_date and exp <= current_date + 30 and not pend),
           count(*),
           string_agg(split_part(full_name, ' ', 1) || ' (' || tname || case when exp is null then ', missing' else ', expired ' || _fmt_date(exp) end || ')', '; ')
             filter (where (exp is null or exp < current_date) and not pend)
      into n_bad, n_pend, n_soon, n_total, v_names from st;
    v_cur := 'Staff register: ' || n_total || ' credentials tracked';
    if n_total = 0 then
      v_status := 'missing'; v_reason := 'No staff credentials of this type are on the register.';
    elsif n_bad > 0 then
      v_status := 'missing'; v_flags := v_flags || 'overdue'::text;
      v_reason := 'Expired or missing: ' || v_names || '.';
    elsif n_pend > 0 then
      v_status := 'under_review'; v_flags := v_flags || 'awaiting_verification'::text;
      v_reason := n_pend || ' renewed certificate' || case when n_pend = 1 then ' is' else 's are' end || ' waiting for verification.';
    else
      v_status := 'compliant';
      v_reason := 'Every credential on the register is current.';
    end if;
    if n_soon > 0 then
      v_flags := v_flags || 'expiring'::text;
      v_reason := v_reason || ' ' || n_soon || ' expire' || case when n_soon = 1 then 's' else '' end || ' within 30 days; the staff agent is chasing the renewals.';
    end if;
    select max(coalesce(cs.reviewed_at, sc.created_at)) into v_last from staff_certificates sc join staff st on st.id = sc.staff_id
      left join certificate_submissions cs on cs.staff_id = st.id and cs.status = 'approved' where st.centre_id = ci.centre_id;

  elsif ci.evidence_kind = 'incidents' then
    v_cur := 'Incident register: ' || (select count(*) from incidents i where i.centre_id = ci.centre_id) || ' records';
    if exists (select 1 from v_incident_deadlines d where d.centre_id = ci.centre_id and (d.parent_status = 'overdue' or d.regulator_status = 'overdue')) then
      v_status := 'missing'; v_flags := v_flags || 'overdue'::text; v_reason := 'An incident notice is overdue.';
    elsif exists (select 1 from v_incident_deadlines d where d.centre_id = ci.centre_id and (d.parent_status = 'pending' or d.regulator_status = 'pending')) then
      v_status := 'under_review'; v_reason := 'An incident notice is due within 24 hours.';
    else
      v_status := 'compliant'; v_reason := 'Every incident notice was sent on time.';
    end if;
    select max(i.created_at) into v_last from incidents i where i.centre_id = ci.centre_id;

  elsif ci.evidence_kind = 'medical' then
    v_cur := 'Medical profiles: ' || (select count(distinct m.child_id) from medical_updates m where m.centre_id = ci.centre_id and m.status = 'approved') || ' reviewed';
    select count(*) into n_pend from medical_updates m where m.centre_id = ci.centre_id and m.status = 'pending';
    if n_pend > 0 then
      v_status := 'under_review';
      v_reason := n_pend || ' parent medical update' || case when n_pend = 1 then ' is' else 's are' end || ' waiting for review.';
      v_flags := v_flags || 'awaiting_verification'::text;
      if exists (select 1 from medical_updates m where m.centre_id = ci.centre_id and m.status = 'pending' and m.submitted_at < now() - interval '2 days') then
        v_flags := v_flags || 'overdue'::text;
      end if;
    else
      v_status := 'compliant'; v_reason := 'All medical updates are reviewed.';
    end if;
    select max(coalesce(m.approved_at, m.submitted_at)) into v_last from medical_updates m where m.centre_id = ci.centre_id;

  else -- children
    select count(*), count(*) filter (where trim(c.emergency_contact) = '') into n_total, n_bad from children c where c.centre_id = ci.centre_id and c.is_active;
    v_cur := n_total || ' active child records';
    if n_total = 0 then v_status := 'missing'; v_reason := 'No child records yet.';
    elsif n_bad > 0 then v_status := 'missing'; v_reason := n_bad || ' child record' || case when n_bad = 1 then ' is' else 's are' end || ' missing an emergency contact.';
    else v_status := 'compliant'; v_reason := 'Every child has a parent and emergency contact on file.'; end if;
    select max(c.created_at) into v_last from children c where c.centre_id = ci.centre_id;
  end if;

  -- a guidance change the owner hasn't decided on yet
  if ci.review_required then
    v_flags := v_flags || 'review_required'::text;
    if v_status = 'compliant' then v_status := 'under_review'; end if;
    v_reason := coalesce(nullif(ci.review_note, ''), 'Review required after a guidance update') || '. ' || v_reason;
  end if;
  -- the linked recurring task is overdue
  v_pat := _item_task_pattern(ci.item_key);
  if v_pat is not null then
    select q.title, r.due_date into v_rec from compliance_records r join compliance_requirements q on q.id = r.requirement_id
     where q.centre_id = ci.centre_id and q.is_active and q.title ~* v_pat and r.status = 'pending' and r.due_date < current_date
     order by r.due_date limit 1;
    if v_rec.title is not null then
      v_flags := v_flags || 'task_overdue'::text;
      v_reason := v_reason || ' The scheduled ' || lower(v_rec.title) || ' was due ' || _fmt_date(v_rec.due_date) || '.';
    end if;
  end if;

  -- priority, and why
  if v_status = 'missing' then
    v_prio := case when _item_critical(ci.item_key) then 'critical' else 'high' end;
    v_prio_reason := case when v_prio = 'critical' then 'Critical: this is a child-safety requirement and the evidence is ' || case when 'overdue' = any (v_flags) then 'out of date' else 'missing' end || '.'
                          else 'High: an officer can ask for this evidence and it is ' || case when 'overdue' = any (v_flags) then 'out of date' else 'missing' end || '.' end;
  elsif v_status = 'under_review' then
    if 'overdue' = any (v_flags) and _item_critical(ci.item_key) then v_prio := 'high'; v_prio_reason := 'High: a child-safety requirement is only covered once the new evidence is verified.';
    elsif 'review_required' = any (v_flags) then v_prio := 'medium'; v_prio_reason := 'Medium: a guidance change may affect this requirement and needs your decision.';
    else v_prio := 'medium'; v_prio_reason := 'Medium: evidence is waiting for verification.'; end if;
  else
    if 'review_due' = any (v_flags) or 'expiring' = any (v_flags) then v_prio := 'medium'; v_prio_reason := 'Medium: compliant now, but evidence expires soon.';
    else v_prio := 'low'; v_prio_reason := 'Low: compliant with verified evidence.'; end if;
  end if;
  if 'task_overdue' = any (v_flags) and v_prio in ('medium', 'low') then
    v_prio := 'high'; v_prio_reason := 'High: the scheduled ' || lower(v_rec.title) || ' is overdue.';
  end if;

  -- what should happen next
  select * into v_task from audit_tasks t where t.checklist_item_id = ci.id and t.state <> 'resolved' and t.kind in ('evidence', 'owner_action')
   order by t.opened_at limit 1;
  select coalesce(split_part(s.full_name, ' ', 1), '') into v_assignee from staff s where s.id = v_task.assignee_staff_id;
  if 'review_required' = any (v_flags) then
    select u.title, rr.decision into v_rev from regulation_reviews rr join regulation_updates u on u.id = rr.regulation_update_id
     where rr.checklist_item_id = ci.id and (rr.decision is null or (rr.decision = 'update_needed' and rr.completed_at is null)) order by rr.created_at desc limit 1;
    v_next := case when v_rev.decision = 'update_needed' then 'Upload the updated policy that reflects “' || v_rev.title || '”, then verify it.'
                   when v_rev.title is not null then 'Review “' || v_rev.title || '” and record whether the policy needs to change.'
                   else 'Review the guidance change and record your decision.' end;
  elsif v_pend.id is not null and ci.evidence_kind = 'document' then
    v_next := 'Check and verify “' || v_pend.title || '”.';
  elsif ci.evidence_kind = 'document' and v_status = 'missing' then
    v_next := case when v_task.id is not null and v_task.assignee_staff_id is not null
                   then 'Waiting for ' || v_assignee || ' to upload it' || case when v_task.next_follow_up is not null then ' (follow-up ' || _fmt_date(v_task.next_follow_up) || ')' else '' end || '.'
                   else 'Upload ' || lower(left(ci.evidence_hint, 1)) || substr(ci.evidence_hint, 2) || '.' end;
  elsif ci.evidence_kind = 'document' and 'review_due' = any (v_flags) then
    v_next := case when v_task.id is not null and v_task.assignee_staff_id is not null then 'Renewal requested from ' || v_assignee || '.'
                   else 'Upload a renewed version before ' || _fmt_date(v_exp) || '.' end;
  elsif ci.evidence_kind = 'certificates' and v_status <> 'compliant' then
    v_next := case when n_bad > 0 then 'The staff agent is chasing the renewals. Decide on its escalations in Staff certifications.'
                   else 'Verify the uploaded certificate' || case when n_pend = 1 then '' else 's' end || ' in Staff certifications.' end;
  elsif ci.evidence_kind = 'certificates' and n_soon > 0 then
    v_next := 'Nothing for you yet: the staff agent is chasing ' || n_soon || ' renewal' || case when n_soon = 1 then '' else 's' end || '.';
  elsif ci.evidence_kind = 'incidents' and v_status <> 'compliant' then v_next := 'Send the outstanding incident notice.';
  elsif ci.evidence_kind = 'medical' and v_status <> 'compliant' then v_next := 'Review the waiting medical update.';
  elsif ci.evidence_kind = 'children' and v_status <> 'compliant' then v_next := 'Add the missing emergency contacts.';
  else
    v_next := case when v_exp is not null then 'None. Next renewal due by ' || _fmt_date(v_exp) || '.' else 'None. beehive keeps watching.' end;
  end if;
  if 'task_overdue' = any (v_flags) then
    v_next := v_next || case when ci.evidence_kind = 'document' and v_status <> 'compliant'
                             then ' Verifying it also completes the overdue ' || lower(v_rec.title) || '.'
                             else ' Also complete the overdue ' || lower(v_rec.title) || '.' end;
  end if;

  return jsonb_build_object(
    'status', v_status, 'label', _req_label(v_status), 'flags', to_jsonb(v_flags), 'reason', trim(v_reason),
    'priority', v_prio, 'priority_reason', v_prio_reason, 'why', _item_why(ci.item_key), 'next_action', trim(v_next),
    'current_evidence', v_cur, 'last_reviewed', coalesce(ci.last_reviewed_at, v_last),
    'evidence_id', v_ev.id, 'evidence_title', v_ev.title, 'evidence_file', v_ev.file_path, 'evidence_date', v_ev.recorded_on, 'evidence_expires', v_exp,
    'pending_evidence_id', v_pend.id, 'open_task_id', v_task.id);
end $$;
revoke execute on function public._requirement_status(uuid) from public, anon;
grant execute on function public._requirement_status(uuid) to authenticated;

-- ---------------------------------------------------------------------------
-- views: same columns the app already reads, plus the agent's fields
-- ---------------------------------------------------------------------------
drop view if exists public.v_readiness;
drop view if exists public.v_checklist_status;
create view public.v_checklist_status with (security_invoker = true) as
select
  ci.id, ci.centre_id, ci.item_key, ci.area, ci.title, ci.source_ref, ci.evidence_hint, ci.evidence_kind,
  ci.summary, ci.risk_note, ci.icon, ci.review_required, ci.review_note, ci.review_months,
  (ci.approved_at is not null) as approved,
  s->>'evidence_title' as evidence_title, s->>'evidence_file' as evidence_file, (s->>'evidence_date')::date as evidence_date,
  case s->>'status' when 'compliant' then 'green' when 'under_review' then 'yellow' else 'red' end as status,
  s->>'reason' as reason,
  s->>'current_evidence' as evidence_text,
  (s->>'last_reviewed')::timestamptz as last_updated,
  s->>'status' as req_status,
  array(select jsonb_array_elements_text(s->'flags')) as flags,
  s->>'priority' as priority, s->>'priority_reason' as priority_reason, s->>'why' as why, s->>'next_action' as next_action,
  (s->>'evidence_expires')::date as evidence_expires, (s->>'pending_evidence_id')::uuid as pending_evidence_id, (s->>'open_task_id')::uuid as open_task_id
from public.checklist_items ci
cross join lateral (select public._requirement_status(ci.id) as s) x
where ci.is_active;
grant select on public.v_checklist_status to authenticated;

-- Readiness from approved requirements: compliant 1, under review 0.5, missing 0.
create view public.v_readiness with (security_invoker = true) as
select centre_id,
  count(*)::int as total_items,
  count(*) filter (where status = 'green')::int as green,
  count(*) filter (where status = 'yellow')::int as yellow,
  count(*) filter (where status = 'red')::int as red,
  case when count(*) = 0 then 0
       else round(100.0 * (count(*) filter (where status = 'green') + 0.5 * count(*) filter (where status = 'yellow')) / count(*))::int end as score
from public.v_checklist_status where approved group by centre_id;
grant select on public.v_readiness to authenticated;

-- ---------------------------------------------------------------------------
-- feed + messages
-- ---------------------------------------------------------------------------
create or replace function public._audit_event(p_centre uuid, p_item uuid, p_task uuid, p_reg uuid, p_kind text, p_state text, p_summary text, p_detail jsonb default '{}')
returns void language plpgsql security definer set search_path = public as $$
begin
  insert into agent_events (centre_id, agent, checklist_item_id, audit_task_id, regulation_update_id, kind, state, summary, detail)
  values (p_centre, 'audit', p_item, p_task, p_reg, p_kind, p_state, p_summary, coalesce(p_detail, '{}'));
  perform log_audit(p_centre, 'audit_agent.' || p_kind, coalesce(case when p_task is not null then 'audit_tasks' end, 'checklist_items'),
    coalesce(p_task::text, p_item::text, p_reg::text, ''), coalesce(p_detail, '{}') || jsonb_build_object('summary', p_summary, 'checklist_item_id', p_item));
end $$;
revoke execute on function public._audit_event(uuid, uuid, uuid, uuid, text, text, text, jsonb) from public, anon, authenticated;

-- Simulated email/SMS to the person asked for evidence.
create or replace function public._audit_send(p_task uuid, p_kind text, p_note text default '')
returns uuid language plpgsql security definer set search_path = public as $$
declare t audit_tasks; ci checklist_items; s staff; c centres; v_owner text; v_channel text; v_to text; v_body text; v_subject text; v_next date; v_id uuid;
begin
  select * into t from audit_tasks where id = p_task;
  select * into ci from checklist_items where id = t.checklist_item_id;
  select * into s from staff where id = t.assignee_staff_id;
  if s.id is null then return null; end if;
  select * into c from centres where id = t.centre_id;
  select coalesce(u.full_name, 'the centre owner') into v_owner from users u where u.centre_id = t.centre_id and u.role = 'owner' limit 1;
  if coalesce(s.email, '') <> '' then v_channel := 'email'; v_to := s.email; elsif coalesce(s.phone, '') <> '' then v_channel := 'sms'; v_to := s.phone; else v_channel := 'none'; v_to := ''; end if;
  v_subject := case p_kind when 'request' then 'Please upload: ' || ci.title when 'follow_up' then 'Reminder: ' || ci.title else 'Please upload again: ' || ci.title end;
  v_body := 'Hi ' || split_part(s.full_name, ' ', 1) || ', ' ||
    case p_kind
      when 'request' then 'for our audit records we need ' || lower(left(ci.evidence_hint, 1)) || substr(ci.evidence_hint, 2) || ' (' || ci.source_ref || '). Please upload it' ||
                          case when t.due_date is not null then ' by ' || _fmt_date(t.due_date) else '' end || ' using your secure link.'
      when 'follow_up' then 'we still need ' || lower(left(ci.evidence_hint, 1)) || substr(ci.evidence_hint, 2) || '. Please upload it using your secure link.'
      else 'the evidence you uploaded for ' || lower(ci.title) || ' couldn’t be accepted' || case when p_note <> '' then ' (' || p_note || ')' else '' end || '. Please upload a corrected version using your secure link.'
    end || ' Thanks, ' || split_part(v_owner, ' ', 1) || ', ' || c.name || '.';
  v_next := current_date + _audit_follow_days(t.priority);
  insert into agent_messages (centre_id, task_id, audit_task_id, staff_id, kind, channel, recipient, subject, body, upload_link, outcome, next_follow_up)
  values (t.centre_id, null, t.id, s.id, p_kind, v_channel, v_to, v_subject, v_body, '/#evidence/' || t.upload_token,
          case when v_channel = 'none' then 'no_contact' else 'simulated' end, v_next)
  returning id into v_id;
  update audit_tasks set requests_sent = requests_sent + 1, last_request_at = now(), next_follow_up = v_next, updated_at = now(),
         state = case when state = 'owner_review' then state else 'waiting' end where id = t.id;
  perform _audit_event(t.centre_id, t.checklist_item_id, t.id, null,
    case p_kind when 'request' then 'evidence_requested' when 'follow_up' then 'evidence_follow_up' else 'evidence_correction' end, 'Action taken',
    case p_kind when 'request' then 'Evidence requested from ' || split_part(s.full_name, ' ', 1) when 'follow_up' then 'Follow-up sent to ' || split_part(s.full_name, ' ', 1)
                else 'Corrected evidence requested from ' || split_part(s.full_name, ' ', 1) end,
    jsonb_build_object('message_id', v_id, 'channel', v_channel, 'recipient', v_to, 'simulated', true, 'next_follow_up', v_next));
  return v_id;
end $$;
revoke execute on function public._audit_send(uuid, text, text) from public, anon, authenticated;

-- Complete the recurring task linked to a requirement (e.g. a verified drill record completes the rehearsal).
create or replace function public._complete_linked_task(p_item uuid, p_on date, p_by uuid, p_note text)
returns void language plpgsql security definer set search_path = public as $$
declare ci checklist_items; v_pat text;
begin
  select * into ci from checklist_items where id = p_item;
  v_pat := _item_task_pattern(ci.item_key);
  if v_pat is null then return; end if;
  update compliance_records r set status = 'completed', completed_on = least(coalesce(p_on, current_date), _local_today()), completed_by = p_by, notes = coalesce(nullif(p_note, ''), 'Evidence verified')
    from compliance_requirements q
   where r.requirement_id = q.id and q.centre_id = ci.centre_id and q.is_active and q.title ~* v_pat and r.status = 'pending';
end $$;
revoke execute on function public._complete_linked_task(uuid, date, uuid, text) from public, anon, authenticated;

-- The old "drill completes rehearsal" rule now applies to any verified evidence for a linked requirement.
create or replace function public._drill_completes_rehearsal()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.status = 'verified' then perform _complete_linked_task(new.checklist_item_id, new.recorded_on, new.uploaded_by, coalesce(nullif(new.title, ''), 'Evidence recorded')); end if;
  return new;
end $$;

-- ---------------------------------------------------------------------------
-- regulation updates: identify what may be affected (not what must change)
-- ---------------------------------------------------------------------------
create or replace function public._assess_regulation(p_update uuid)
returns int language plpgsql security definer set search_path = public as $$
declare u regulation_updates; ci record; v_impact text; v_reason text; n int := 0; v_task uuid; v_text text; v_titles text := '';
begin
  select * into u from regulation_updates where id = p_update;
  v_text := lower(u.title || ' ' || u.summary);
  for ci in select * from checklist_items where centre_id = u.centre_id and is_active and approved_at is not null loop
    v_impact := null;
    if exists (select 1 from unnest(u.match_terms) t where ci.item_key = t or ci.title ilike '%' || t || '%') then
      v_impact := 'likely';
      v_reason := 'The update is about ' || lower(ci.title) || ', which your checklist covers.';
    elsif ci.item_key is not null and (v_text like '%' || ci.item_key || '%' or (ci.item_key = 'sleep' and v_text ~ 'sleep|rest')
          or (ci.item_key = 'sun' and v_text ~ 'sun |uv') or (ci.item_key = 'evacuation' and v_text ~ 'evacuat|emergency drill')) then
      v_impact := 'possible';
      v_reason := 'The update mentions ' || lower(ci.title) || ', so it may be relevant.';
    end if;
    if v_impact is null then continue; end if;
    insert into regulation_reviews (centre_id, regulation_update_id, checklist_item_id, impact, reason, recommended)
    values (u.centre_id, u.id, ci.id, v_impact, v_reason,
            'Compare your current ' || lower(ci.title) || ' evidence with the new guidance. Record “no change needed” if it already complies, or upload an updated version if it doesn’t.')
    on conflict do nothing;
    update checklist_items set review_required = true, review_note = 'Review required: ' || u.title where id = ci.id;
    insert into audit_tasks (centre_id, checklist_item_id, kind, title, reason, recommended_action, priority, state, regulation_update_id, due_date)
    values (u.centre_id, ci.id, 'regulation_review', 'Review ' || ci.title || ' against “' || u.title || '”', v_reason,
            'Read the update, compare it with your current evidence and record your decision. beehive won’t change the policy or the status for you.',
            'medium', 'owner_review', u.id, current_date + 14)
    on conflict do nothing returning id into v_task;
    perform _audit_event(u.centre_id, ci.id, v_task, u.id, 'review_required', 'Owner review', 'Review required: ' || ci.title,
      jsonb_build_object('impact', v_impact, 'reason', v_reason, 'update', u.title));
    v_titles := v_titles || case when v_titles = '' then '' else ', ' end || ci.title;
    n := n + 1;
  end loop;
  if n = 0 then
    insert into regulation_reviews (centre_id, regulation_update_id, checklist_item_id, impact, reason, recommended)
    values (u.centre_id, u.id, null, 'unclear', 'beehive couldn’t match this update to a requirement in your checklist.', 'Read the update and confirm whether it applies to your centre.')
    on conflict do nothing;
    insert into audit_tasks (centre_id, kind, title, reason, recommended_action, priority, state, regulation_update_id, due_date)
    values (u.centre_id, 'regulation_review', 'Confirm whether “' || u.title || '” applies', 'No checklist requirement clearly matches this update, so the impact is uncertain.',
            'Read the update and record whether it applies.', 'medium', 'owner_review', u.id, current_date + 14)
    on conflict do nothing;
  end if;
  update regulation_updates set status = 'assessed', assessed_at = now(),
    assessment = case when n = 0 then 'Impact unclear: no requirement clearly matches. Flagged for your review.'
                      else 'May affect ' || n || ' requirement' || case when n = 1 then '' else 's' end || ': ' || v_titles || '. This identifies a potentially relevant change; it doesn’t confirm your policy must change.' end,
    affected_summary = coalesce(nullif(v_titles, ''), affected_summary)
   where id = u.id;
  perform _audit_event(u.centre_id, null, null, u.id, 'regulation_assessed', 'Action taken', 'Regulation change assessed: ' || u.title,
    jsonb_build_object('affected', n, 'items', v_titles));
  return n;
end $$;
revoke execute on function public._assess_regulation(uuid) from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- the loop
-- ---------------------------------------------------------------------------
create or replace function public.run_audit_agent_for(p_centre uuid, p_trigger text default 'app')
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  ci checklist_items; s jsonb; v_status text; v_prio text; t audit_tasks; v_flags text[]; v_assignee uuid; r record; v_pat text; v_any boolean;
  n_gaps int := 0; n_changes int := 0; n_requests int := 0; n_follow int := 0; n_tasks int := 0; n_resolved int := 0; n_reg int := 0; n_esc int := 0;
begin
  if not exists (select 1 from checklist_items where centre_id = p_centre and is_active and approved_at is not null) then
    return jsonb_build_object('skipped', 'checklist not approved');
  end if;
  -- 1. regulation updates waiting to be assessed
  for r in select id from regulation_updates where centre_id = p_centre and status = 'new' loop
    perform _assess_regulation(r.id); n_reg := n_reg + 1;
  end loop;

  -- 2. every approved requirement
  for ci in select * from checklist_items where centre_id = p_centre and is_active and approved_at is not null order by area, title loop
    s := _requirement_status(ci.id);
    v_status := s->>'status'; v_prio := s->>'priority';
    v_flags := array(select jsonb_array_elements_text(s->'flags'));
    if ci.agent_status is null then
      if v_status <> 'compliant' then
        perform _audit_event(p_centre, ci.id, null, null, 'gap_detected', 'Monitoring',
          case v_status when 'missing' then 'Gap detected: ' else 'Needs review: ' end || ci.title,
          jsonb_build_object('status', v_status, 'reason', s->>'reason', 'priority', v_prio, 'priority_reason', s->>'priority_reason', 'why', s->>'why', 'next_action', s->>'next_action'));
        n_gaps := n_gaps + 1;
      end if;
    elsif ci.agent_status <> v_status then
      perform _audit_event(p_centre, ci.id, null, null, 'status_changed', case when v_status = 'compliant' then 'Resolved' else 'Monitoring' end,
        _req_label(ci.agent_status) || ' → ' || _req_label(v_status) || ': ' || ci.title,
        jsonb_build_object('from', ci.agent_status, 'to', v_status, 'reason', s->>'reason', 'priority', v_prio, 'priority_reason', s->>'priority_reason'));
      n_changes := n_changes + 1;
    end if;
    update checklist_items set agent_status = v_status, agent_priority = v_prio where id = ci.id;

    -- evidence collection for document requirements
    if ci.evidence_kind = 'document' then
      select * into t from audit_tasks where checklist_item_id = ci.id and kind = 'evidence' and state <> 'resolved';
      if s->>'pending_evidence_id' is not null then
        if t.id is null then
          insert into audit_tasks (centre_id, checklist_item_id, kind, title, reason, recommended_action, priority, state, evidence_id)
          values (p_centre, ci.id, 'evidence', 'Verify evidence for ' || ci.title, s->>'reason', 'Check the uploaded evidence against the requirement and verify or reject it.',
                  case when v_prio = 'low' then 'medium' else v_prio end, 'owner_review', (s->>'pending_evidence_id')::uuid);
          n_tasks := n_tasks + 1;
        elsif t.state <> 'owner_review' or t.evidence_id is distinct from (s->>'pending_evidence_id')::uuid then
          update audit_tasks set state = 'owner_review', evidence_id = (s->>'pending_evidence_id')::uuid, updated_at = now() where id = t.id;
        end if;
      elsif v_status = 'missing' or (v_status = 'compliant' and 'review_due' = any (v_flags) and (s->>'evidence_expires')::date <= current_date + 14) then
        if t.id is null then
          v_assignee := _item_default_assignee(ci);
          insert into audit_tasks (centre_id, checklist_item_id, kind, title, reason, recommended_action, priority, state, assignee_staff_id, due_date)
          values (p_centre, ci.id, 'evidence', case when v_status = 'missing' then 'Collect evidence for ' else 'Renew evidence for ' end || ci.title,
                  s->>'reason', 'Upload ' || lower(left(ci.evidence_hint, 1)) || substr(ci.evidence_hint, 2) || '.',
                  case when v_prio = 'low' then 'medium' else v_prio end, 'waiting', v_assignee,
                  case when v_status = 'missing' then current_date + _audit_follow_days(v_prio) + 2 else (s->>'evidence_expires')::date end)
          returning * into t;
          n_tasks := n_tasks + 1;
          if v_assignee is not null then
            perform _audit_send(t.id, 'request'); n_requests := n_requests + 1;
          else
            perform _audit_event(p_centre, ci.id, t.id, null, 'action_proposed', 'Waiting', 'Proposed for you: upload evidence for ' || ci.title,
              jsonb_build_object('next_action', t.recommended_action, 'priority', t.priority, 'proposed', true));
          end if;
        else
          if t.priority is distinct from v_prio and v_prio <> 'low' then update audit_tasks set priority = v_prio, updated_at = now() where id = t.id; end if;
          if t.state = 'owner_review' and t.escalated_at is null then update audit_tasks set state = 'waiting', evidence_id = null where id = t.id; end if;
          if t.assignee_staff_id is not null and t.next_follow_up is not null and t.next_follow_up <= current_date then
            if t.requests_sent >= 3 and t.escalated_at is null then
              update audit_tasks set escalated_at = now(), state = 'owner_review',
                recommended_action = 'Speak to ' || (select split_part(full_name, ' ', 1) from staff where id = t.assignee_staff_id) || ' or assign the task to someone else.'
               where id = t.id;
              perform _audit_event(p_centre, ci.id, t.id, null, 'escalated', 'Owner review', 'Escalated to you: ' || ci.title,
                jsonb_build_object('reason', 'No response after ' || t.requests_sent || ' requests.'));
              n_esc := n_esc + 1;
            elsif t.escalated_at is null then
              perform _audit_send(t.id, 'follow_up'); n_follow := n_follow + 1;
            end if;
          end if;
        end if;
      elsif t.id is not null and v_status = 'compliant' then
        update audit_tasks set state = 'resolved', resolved_at = now(), resolution = 'Verified evidence on file', updated_at = now() where id = t.id;
        perform _audit_event(p_centre, ci.id, t.id, null, 'resolved', 'Resolved', 'Gap closed: ' || ci.title, jsonb_build_object('reason', s->>'reason'));
        n_resolved := n_resolved + 1;
      end if;
    elsif ci.evidence_kind in ('medical', 'incidents', 'children') then
      select * into t from audit_tasks where checklist_item_id = ci.id and kind = 'owner_action' and state <> 'resolved';
      if v_status <> 'compliant' and t.id is null then
        insert into audit_tasks (centre_id, checklist_item_id, kind, title, reason, recommended_action, priority, state)
        values (p_centre, ci.id, 'owner_action', ci.title || ': ' || lower(s->>'next_action'), s->>'reason', s->>'next_action', case when v_prio = 'low' then 'medium' else v_prio end, 'waiting')
        returning * into t;
        perform _audit_event(p_centre, ci.id, t.id, null, 'action_proposed', 'Waiting', 'Proposed for you: ' || lower(s->>'next_action'),
          jsonb_build_object('reason', s->>'reason', 'proposed', true));
        n_tasks := n_tasks + 1;
      elsif v_status = 'compliant' and t.id is not null then
        update audit_tasks set state = 'resolved', resolved_at = now(), resolution = s->>'reason', updated_at = now() where id = t.id;
        perform _audit_event(p_centre, ci.id, t.id, null, 'resolved', 'Resolved', 'Gap closed: ' || ci.title, jsonb_build_object('reason', s->>'reason'));
        n_resolved := n_resolved + 1;
      end if;
    end if;
    -- certificate requirements are handled by the staff agent: nothing to send from here
  end loop;

  -- 3. overdue recurring compliance tasks
  for r in
    select rec.id as record_id, q.title, rec.due_date, q.regulation_reference,
           (select ci2.id from checklist_items ci2 where ci2.centre_id = p_centre and ci2.is_active and ci2.approved_at is not null
              and _item_task_pattern(ci2.item_key) is not null and q.title ~* _item_task_pattern(ci2.item_key) limit 1) as item_id
    from compliance_records rec join compliance_requirements q on q.id = rec.requirement_id
    where q.centre_id = p_centre and q.is_active and rec.status = 'pending' and rec.due_date < current_date
  loop
    if not exists (select 1 from audit_tasks where compliance_record_id = r.record_id and kind = 'overdue_task' and state <> 'resolved') then
      insert into audit_tasks (centre_id, checklist_item_id, kind, title, reason, recommended_action, priority, state, compliance_record_id, due_date)
      values (p_centre, r.item_id, 'overdue_task', 'Complete the overdue ' || lower(r.title),
              'Due ' || _fmt_date(r.due_date) || ' (' || r.regulation_reference || '). Overdue scheduled tasks are one of the first things an officer checks.',
              'Do it, record it on the Compliance page and attach any evidence.', 'high', 'waiting', r.record_id, r.due_date)
      returning * into t;
      perform _audit_event(p_centre, r.item_id, t.id, null, 'task_overdue', 'Waiting', 'Overdue: ' || r.title,
        jsonb_build_object('due_date', r.due_date, 'regulation', r.regulation_reference, 'proposed', true));
      n_tasks := n_tasks + 1;
    end if;
  end loop;
  for t in select a.* from audit_tasks a where a.centre_id = p_centre and a.kind = 'overdue_task' and a.state <> 'resolved'
           and not exists (select 1 from compliance_records rec where rec.id = a.compliance_record_id and rec.status = 'pending') loop
    update audit_tasks set state = 'resolved', resolved_at = now(), resolution = 'Task completed', updated_at = now() where id = t.id;
    perform _audit_event(p_centre, t.checklist_item_id, t.id, null, 'resolved', 'Resolved', 'Done: ' || replace(t.title, 'Complete the overdue ', ''), '{}');
    n_resolved := n_resolved + 1;
  end loop;

  insert into agent_runs (centre_id, agent, trigger, summary) values (p_centre, 'audit', p_trigger, jsonb_build_object(
    'gaps', n_gaps, 'status_changes', n_changes, 'requests', n_requests, 'follow_ups', n_follow, 'tasks', n_tasks, 'resolved', n_resolved, 'regulation_updates', n_reg, 'escalated', n_esc));
  return jsonb_build_object('gaps', n_gaps, 'status_changes', n_changes, 'requests', n_requests, 'follow_ups', n_follow, 'tasks', n_tasks,
    'resolved', n_resolved, 'regulation_updates', n_reg, 'escalated', n_esc, 'ran_at', now());
end $$;
revoke execute on function public.run_audit_agent_for(uuid, text) from public, anon, authenticated;

create or replace function public.run_audit_agent()
returns jsonb language plpgsql security definer set search_path = public as $$
begin
  if not is_leader() then raise exception 'Only the owner or director can run the agent'; end if;
  return run_audit_agent_for(my_centre_id(), 'app');
end $$;
grant execute on function public.run_audit_agent() to authenticated;

-- The daily schedule now runs both agents.
create or replace function public.run_staff_agent_all()
returns int language plpgsql security definer set search_path = public as $$
declare c record; n int := 0;
begin
  for c in select id from centres loop
    perform run_staff_agent_for(c.id, 'schedule');
    perform run_audit_agent_for(c.id, 'schedule');
    n := n + 1;
  end loop;
  return n;
end $$;
revoke execute on function public.run_staff_agent_all() from public, anon, authenticated;

-- (The app runs the agent straight after the checklist is approved, and the daily schedule runs it every morning.)

-- ---------------------------------------------------------------------------
-- evidence: submit (assessed), verify or reject (owner), self-attested records
-- ---------------------------------------------------------------------------
create or replace function public._submit_evidence(p_item checklist_items, p_title text, p_file_name text, p_file_data text, p_file_path text,
  p_hash text, p_extracted jsonb, p_date date, p_source text, p_by uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_ext jsonb := coalesce(p_extracted, '{}'); v_checks jsonb := '[]'; v_flag text; v_dup record; v_doc date; v_date date; v_exp date;
  v_id uuid; t audit_tasks; v_resolves boolean; v_readable boolean;
begin
  if coalesce(p_hash, '') <> '' then
    select e.id, e.status, e.created_at into v_dup from evidence e
     where e.checklist_item_id = p_item.id and e.file_hash = p_hash and e.status in ('pending', 'verified') order by e.created_at desc limit 1;
    if v_dup.id is not null then
      raise exception 'This file was already uploaded on % and is %.', _fmt_date(v_dup.created_at::date),
        case when v_dup.status = 'pending' then 'waiting for verification' else 'already verified' end;
    end if;
  end if;
  v_readable := coalesce((v_ext->>'readable')::boolean, false);
  v_doc := nullif(v_ext->>'document_date', '')::date;
  v_date := coalesce(p_date, v_doc);
  if not v_readable then
    v_checks := v_checks || jsonb_build_object('field', 'document', 'issue', 'unreadable', 'message', 'beehive couldn’t read this file. Check it’s the right document before verifying.');
  else
    if coalesce((v_ext->>'topic_match')::boolean, true) = false then
      v_checks := v_checks || jsonb_build_object('field', 'topic', 'issue', 'mismatch', 'message', 'This doesn’t look like ' || lower(p_item.evidence_hint) || '.');
    end if;
    if v_doc is null then
      v_checks := v_checks || jsonb_build_object('field', 'date', 'issue', 'missing', 'message', 'No date found in the document, so beehive can’t tell if it’s current.');
    end if;
  end if;
  if v_date is not null and v_date > _local_today() then
    v_checks := v_checks || jsonb_build_object('field', 'date', 'issue', 'future', 'message', 'The date (' || _fmt_date(v_date) || ') is in the future.');
  end if;
  if v_date is not null then
    v_exp := (v_date + make_interval(months => p_item.review_months))::date;
    if v_exp < current_date then
      v_checks := v_checks || jsonb_build_object('field', 'date', 'issue', 'out_of_date', 'message', 'Dated ' || _fmt_date(v_date) || ', so it expired on ' || _fmt_date(v_exp) || ' and wouldn’t close the gap.');
    end if;
  end if;
  if p_date is not null and v_doc is not null and p_date <> v_doc then
    v_checks := v_checks || jsonb_build_object('field', 'date', 'issue', 'differs', 'message', 'The date entered (' || _fmt_date(p_date) || ') differs from the date in the document (' || _fmt_date(v_doc) || ').');
  end if;
  if jsonb_typeof(v_ext->'uncertain') = 'array' then
    select v_checks || coalesce(jsonb_agg(jsonb_build_object('field', 'document', 'issue', 'uncertain', 'message', u)), '[]')
      into v_checks from jsonb_array_elements_text(v_ext->'uncertain') u;
  end if;
  v_flag := case when not v_readable then 'unreadable' when jsonb_array_length(v_checks) > 0 then 'needs_check' else 'clear' end;
  v_resolves := v_flag = 'clear' and v_date is not null and v_exp >= current_date;

  update evidence set status = 'superseded', review_note = 'Replaced by a newer upload' where checklist_item_id = p_item.id and status = 'pending';
  insert into evidence (centre_id, checklist_item_id, title, file_path, file_name, file_data, file_hash, recorded_on, uploaded_by, status, extracted, checks, review_flag, source, note)
  values (p_item.centre_id, p_item.id, coalesce(nullif(trim(p_title), ''), p_file_name, 'Evidence'), p_file_path, coalesce(p_file_name, ''), p_file_data, p_hash,
          coalesce(v_date, current_date), p_by, 'pending', v_ext, v_checks, v_flag, p_source,
          case when v_date is null then 'Date not confirmed' else '' end)
  returning id into v_id;

  select * into t from audit_tasks where checklist_item_id = p_item.id and kind = 'evidence' and state <> 'resolved';
  if t.id is null then
    insert into audit_tasks (centre_id, checklist_item_id, kind, title, reason, recommended_action, priority, state, evidence_id)
    values (p_item.centre_id, p_item.id, 'evidence', 'Verify evidence for ' || p_item.title, 'New evidence uploaded.', 'Check the uploaded evidence and verify or reject it.',
            'medium', 'owner_review', v_id) returning * into t;
  else
    update audit_tasks set state = 'owner_review', evidence_id = v_id, updated_at = now() where id = t.id;
  end if;
  perform _audit_event(p_item.centre_id, p_item.id, t.id, null, 'evidence_received', 'Owner review', 'Evidence received: ' || p_item.title,
    jsonb_build_object('evidence_id', v_id, 'source', p_source, 'file_name', p_file_name, 'date', v_date));
  perform _audit_event(p_item.centre_id, p_item.id, t.id, null, 'evidence_assessed', 'Owner review',
    case when v_resolves then 'Would close the gap once verified' when v_flag = 'unreadable' then 'Evidence unreadable: needs checking' else 'Evidence needs checking' end,
    jsonb_build_object('evidence_id', v_id, 'checks', v_checks, 'resolves', v_resolves, 'expires', v_exp));
  perform run_audit_agent_for(p_item.centre_id, 'evidence');
  return jsonb_build_object('id', v_id, 'flag', v_flag, 'checks', v_checks, 'resolves', v_resolves, 'expires', v_exp);
end $$;
revoke execute on function public._submit_evidence(checklist_items, text, text, text, text, text, jsonb, date, text, uuid) from public, anon, authenticated;

create or replace function public.submit_evidence(p_item uuid, p_title text, p_file_name text, p_file_data text default null, p_file_path text default null,
  p_hash text default null, p_extracted jsonb default '{}', p_date date default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare ci checklist_items;
begin
  if not is_staff() then raise exception 'Only centre staff can add evidence'; end if;
  select * into ci from checklist_items where id = p_item and centre_id = my_centre_id() and is_active;
  if ci.id is null then raise exception 'Checklist item not found'; end if;
  if ci.evidence_kind <> 'document' then raise exception 'This requirement is checked from beehive’s own records, not from uploads.'; end if;
  if p_file_data is not null and length(p_file_data) > 4000000 then raise exception 'That file is too large. Use a PDF or photo under 3 MB.'; end if;
  return _submit_evidence(ci, p_title, p_file_name, p_file_data, p_file_path, p_hash, p_extracted, p_date, case when is_leader() then 'owner' else 'staff' end, auth.uid());
end $$;
grant execute on function public.submit_evidence(uuid, text, text, text, text, text, jsonb, date) to authenticated;

create or replace function public.evidence_request_info(p_token uuid)
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object('first_name', split_part(s.full_name, ' ', 1), 'centre', c.name, 'item_id', ci.id, 'title', ci.title, 'evidence_hint', ci.evidence_hint,
           'source_ref', ci.source_ref, 'review_months', ci.review_months, 'item_key', ci.item_key, 'due_date', t.due_date,
           'pending', exists (select 1 from evidence e where e.checklist_item_id = ci.id and e.status = 'pending'))
  from audit_tasks t join checklist_items ci on ci.id = t.checklist_item_id join centres c on c.id = t.centre_id
  left join staff s on s.id = t.assignee_staff_id
  where t.upload_token = p_token and t.state <> 'resolved' and t.kind = 'evidence';
$$;
grant execute on function public.evidence_request_info(uuid) to anon, authenticated;

create or replace function public.submit_evidence_by_token(p_token uuid, p_title text, p_file_name text, p_file_data text,
  p_hash text default null, p_extracted jsonb default '{}', p_date date default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare t audit_tasks; ci checklist_items; v_user uuid;
begin
  select * into t from audit_tasks where upload_token = p_token and state <> 'resolved' and kind = 'evidence';
  if t.id is null then raise exception 'This upload link has expired or the evidence is already verified.'; end if;
  if coalesce(p_file_data, '') = '' then raise exception 'Choose a photo or PDF first.'; end if;
  if length(p_file_data) > 4000000 then raise exception 'That file is too large. Use a PDF or photo under 3 MB.'; end if;
  select * into ci from checklist_items where id = t.checklist_item_id;
  select user_id into v_user from staff where id = t.assignee_staff_id;
  return _submit_evidence(ci, p_title, p_file_name, p_file_data, null, p_hash, p_extracted, p_date, 'link', v_user);
end $$;
grant execute on function public.submit_evidence_by_token(uuid, text, text, text, text, jsonb, date) to anon, authenticated;

-- Owner's decision on uploaded evidence.
create or replace function public.verify_evidence(p_evidence uuid, p_approve boolean, p_date date default null, p_reason text default '')
returns jsonb language plpgsql security definer set search_path = public as $$
declare e evidence; ci checklist_items; v_date date; v_exp date; t audit_tasks; v_before jsonb; v_after jsonb;
begin
  if not is_leader() then raise exception 'Only the owner or director can verify evidence'; end if;
  select * into e from evidence where id = p_evidence and centre_id = my_centre_id() for update;
  if e.id is null then raise exception 'Evidence not found'; end if;
  if e.status <> 'pending' then raise exception 'This evidence has already been %.', case e.status when 'verified' then 'verified' when 'rejected' then 'rejected' else 'replaced by a newer upload' end; end if;
  select * into ci from checklist_items where id = e.checklist_item_id;
  select * into t from audit_tasks where checklist_item_id = ci.id and kind = 'evidence' and state <> 'resolved';
  v_before := _requirement_status(ci.id);
  if p_approve then
    v_date := coalesce(p_date, e.recorded_on);
    if v_date is null then raise exception 'Enter the document date before verifying.'; end if;
    if v_date > _local_today() then raise exception 'The document date can’t be in the future.'; end if;
    v_exp := (v_date + make_interval(months => ci.review_months))::date;
    if v_exp < current_date then
      raise exception 'Evidence dated % expired on %, so it can’t make this requirement compliant. Reject it and ask for a current version.', _fmt_date(v_date), _fmt_date(v_exp);
    end if;
    update evidence set status = 'verified', recorded_on = v_date, verified_by = auth.uid(), verified_at = now(), review_note = coalesce(p_reason, '') where id = e.id;
    update checklist_items set last_reviewed_at = now(), reviewed_by = auth.uid() where id = ci.id;
    perform _complete_linked_task(ci.id, v_date, auth.uid(), 'Evidence verified: ' || e.title);
    -- an updated policy that the owner asked for after a guidance change closes that review
    if exists (select 1 from regulation_reviews rr where rr.checklist_item_id = ci.id and rr.decision = 'update_needed' and rr.completed_at is null) then
      update regulation_reviews set completed_at = now() where checklist_item_id = ci.id and decision = 'update_needed' and completed_at is null;
      if not exists (select 1 from regulation_reviews rr where rr.checklist_item_id = ci.id and (rr.decision is null or (rr.decision = 'update_needed' and rr.completed_at is null))) then
        update checklist_items set review_required = false, review_note = '' where id = ci.id;
      end if;
    end if;
    perform log_audit(ci.centre_id, 'evidence.verified', 'evidence', e.id::text, jsonb_build_object('checklist_item_id', ci.id, 'date', v_date, 'title', e.title));
    perform _audit_event(ci.centre_id, ci.id, t.id, null, 'evidence_verified', 'Resolved', 'Evidence verified: ' || ci.title,
      jsonb_build_object('evidence_id', e.id, 'date', v_date, 'valid_until', v_exp, 'verified_at', now()));
  else
    if coalesce(trim(p_reason), '') = '' then raise exception 'Say why the evidence is being rejected.'; end if;
    update evidence set status = 'rejected', review_note = p_reason, verified_by = auth.uid(), verified_at = now() where id = e.id;
    perform log_audit(ci.centre_id, 'evidence.rejected', 'evidence', e.id::text, jsonb_build_object('checklist_item_id', ci.id, 'reason', p_reason));
    perform _audit_event(ci.centre_id, ci.id, t.id, null, 'evidence_rejected', 'Action taken', 'Evidence rejected: ' || ci.title, jsonb_build_object('evidence_id', e.id, 'reason', p_reason));
    if t.id is not null then
      update audit_tasks set state = 'waiting', evidence_id = null, updated_at = now() where id = t.id;
      if t.assignee_staff_id is not null then perform _audit_send(t.id, 'correction', p_reason); end if;
    end if;
  end if;
  perform run_audit_agent_for(ci.centre_id, 'verification');
  v_after := _requirement_status(ci.id);
  return jsonb_build_object('approved', p_approve, 'before', v_before->>'status', 'after', v_after->>'status', 'valid_until', v_exp);
end $$;
grant execute on function public.verify_evidence(uuid, boolean, date, text) to authenticated;

-- The owner records something they did themselves (for example the drill they ran). Self-attested and recorded as theirs.
create or replace function public.record_evidence(p_item uuid, p_title text, p_date date, p_details jsonb default '{}')
returns jsonb language plpgsql security definer set search_path = public as $$
declare ci checklist_items; v_id uuid;
begin
  if not is_leader() then raise exception 'Only the owner or director can record evidence directly. Staff upload it for verification.'; end if;
  select * into ci from checklist_items where id = p_item and centre_id = my_centre_id() and is_active;
  if ci.id is null then raise exception 'Checklist item not found'; end if;
  if p_date is null or p_date > _local_today() then raise exception 'Enter the date it happened.'; end if;
  if (p_date + make_interval(months => ci.review_months))::date < current_date then raise exception 'That date is too old to count for this requirement.'; end if;
  update evidence set status = 'superseded', review_note = 'Replaced by an owner record' where checklist_item_id = ci.id and status = 'pending';
  insert into evidence (centre_id, checklist_item_id, title, recorded_on, uploaded_by, status, verified_by, verified_at, source, details, note)
  values (ci.centre_id, ci.id, p_title, p_date, auth.uid(), 'verified', auth.uid(), now(), 'owner_record', coalesce(p_details, '{}'), 'Recorded and attested by the owner')
  returning id into v_id;
  update checklist_items set last_reviewed_at = now(), reviewed_by = auth.uid() where id = ci.id;
  perform _audit_event(ci.centre_id, ci.id, null, null, 'evidence_recorded', 'Resolved', 'Recorded by you: ' || p_title, jsonb_build_object('evidence_id', v_id, 'date', p_date, 'details', p_details));
  perform run_audit_agent_for(ci.centre_id, 'evidence');
  return jsonb_build_object('id', v_id);
end $$;
grant execute on function public.record_evidence(uuid, text, date, jsonb) to authenticated;

-- ---------------------------------------------------------------------------
-- regulation decisions (the owner confirms whether anything has to change)
-- ---------------------------------------------------------------------------
create or replace function public.decide_regulation_review(p_review uuid, p_decision text, p_note text default '')
returns jsonb language plpgsql security definer set search_path = public as $$
declare rr regulation_reviews; u regulation_updates; ci checklist_items; t audit_tasks; v_open int;
begin
  if not is_leader() then raise exception 'Only the owner or director can record this decision'; end if;
  if p_decision not in ('no_change', 'update_needed', 'not_applicable') then raise exception 'Unknown decision'; end if;
  select * into rr from regulation_reviews where id = p_review and centre_id = my_centre_id() for update;
  if rr.id is null then raise exception 'Review not found'; end if;
  if rr.decision is not null then raise exception 'You already recorded a decision for this.'; end if;
  select * into u from regulation_updates where id = rr.regulation_update_id;
  select * into ci from checklist_items where id = rr.checklist_item_id;
  update regulation_reviews set decision = p_decision, note = coalesce(p_note, ''), decided_by = auth.uid(), decided_at = now(),
    completed_at = case when p_decision = 'update_needed' then null else now() end where id = rr.id;
  update audit_tasks set state = 'resolved', resolved_at = now(), updated_at = now(),
    resolution = case p_decision when 'no_change' then 'Reviewed: no change needed' when 'not_applicable' then 'Doesn’t apply to this centre' else 'Policy needs updating' end
   where regulation_update_id = u.id and kind = 'regulation_review' and state <> 'resolved' and checklist_item_id is not distinct from rr.checklist_item_id;
  if ci.id is not null then
    if p_decision = 'update_needed' then
      update checklist_items set review_note = 'Update needed after “' || u.title || '”' where id = ci.id;
      select * into t from audit_tasks where checklist_item_id = ci.id and kind = 'evidence' and state <> 'resolved';
      if t.id is null then
        insert into audit_tasks (centre_id, checklist_item_id, kind, title, reason, recommended_action, priority, state, due_date, regulation_update_id)
        values (ci.centre_id, ci.id, 'evidence', 'Update ' || ci.title, 'You decided the policy needs updating after “' || u.title || '”.',
                'Update the policy, upload it and verify it. The requirement stays under review until then.', 'medium', 'waiting', current_date + 30, u.id);
      end if;
    elsif not exists (select 1 from regulation_reviews x where x.checklist_item_id = ci.id and x.id <> rr.id and (x.decision is null or (x.decision = 'update_needed' and x.completed_at is null))) then
      update checklist_items set review_required = false, review_note = '', last_reviewed_at = case when p_decision = 'no_change' then now() else last_reviewed_at end,
             reviewed_by = case when p_decision = 'no_change' then auth.uid() else reviewed_by end
       where id = ci.id;
    end if;
  end if;
  perform log_audit(u.centre_id, 'regulation_update.decision', 'regulation_reviews', rr.id::text,
    jsonb_build_object('update', u.title, 'item', ci.title, 'decision', p_decision, 'note', p_note));
  perform _audit_event(u.centre_id, ci.id, null, u.id, 'regulation_decision', case when p_decision = 'update_needed' then 'Waiting' else 'Resolved' end,
    case p_decision when 'no_change' then 'You confirmed no change needed: ' when 'not_applicable' then 'You marked as not applicable: ' else 'You decided an update is needed: ' end || coalesce(ci.title, u.title),
    jsonb_build_object('decision', p_decision, 'note', p_note, 'update', u.title));
  select count(*) into v_open from regulation_reviews where regulation_update_id = u.id and decision is null;
  if v_open = 0 then
    update regulation_updates set status = 'reviewed', reviewed_at = now() where id = u.id;
    perform _audit_event(u.centre_id, null, null, u.id, 'regulation_reviewed', 'Resolved', 'Regulation review recorded: ' || u.title, '{}');
  end if;
  perform run_audit_agent_for(u.centre_id, 'regulation_decision');
  return jsonb_build_object('decision', p_decision, 'update_status', case when v_open = 0 then 'reviewed' else 'assessed' end);
end $$;
grant execute on function public.decide_regulation_review(uuid, text, text) to authenticated;

-- ---------------------------------------------------------------------------
-- small owner actions
-- ---------------------------------------------------------------------------
create or replace function public.assign_audit_task(p_task uuid, p_staff uuid default null)
returns void language plpgsql security definer set search_path = public as $$
declare t audit_tasks; ci checklist_items;
begin
  if not is_leader() then raise exception 'Only the owner or director can assign tasks'; end if;
  select * into t from audit_tasks where id = p_task and centre_id = my_centre_id();
  if t.id is null or t.state = 'resolved' then raise exception 'This task is already complete.'; end if;
  if t.kind <> 'evidence' then raise exception 'Only evidence requests can be assigned.'; end if;
  if p_staff is not null and not exists (select 1 from staff where id = p_staff and centre_id = t.centre_id and is_active) then raise exception 'Staff member not found'; end if;
  update audit_tasks set assignee_staff_id = p_staff, escalated_at = null, requests_sent = 0, next_follow_up = null,
         state = case when evidence_id is not null then 'owner_review' else 'waiting' end, updated_at = now() where id = t.id;
  select * into ci from checklist_items where id = t.checklist_item_id;
  if p_staff is not null then perform _audit_send(t.id, 'request');
  else perform _audit_event(t.centre_id, ci.id, t.id, null, 'action_proposed', 'Waiting', 'Assigned to you: ' || ci.title, jsonb_build_object('proposed', true)); end if;
end $$;
grant execute on function public.assign_audit_task(uuid, uuid) to authenticated;

create or replace function public.audit_send_now(p_task uuid)
returns uuid language plpgsql security definer set search_path = public as $$
declare t audit_tasks;
begin
  if not is_leader() then raise exception 'Only the owner or director can do this'; end if;
  select * into t from audit_tasks where id = p_task and centre_id = my_centre_id();
  if t.id is null or t.state = 'resolved' then raise exception 'This task is already complete.'; end if;
  if t.assignee_staff_id is null then raise exception 'Assign the task to a staff member first.'; end if;
  return _audit_send(t.id, case when t.requests_sent = 0 then 'request' else 'follow_up' end);
end $$;
grant execute on function public.audit_send_now(uuid) to authenticated;

-- ---------------------------------------------------------------------------
-- views for the interface
-- ---------------------------------------------------------------------------
create or replace view public.v_audit_tasks with (security_invoker = on) as
select t.*, ci.title as item_title, ci.item_key, ci.area, s.full_name as assignee_name, s.email as assignee_email, u.title as update_title,
       q.title as compliance_title, lm.sent_at as last_message_at, lm.channel as last_channel, lm.kind as last_kind
from public.audit_tasks t
left join public.checklist_items ci on ci.id = t.checklist_item_id
left join public.staff s on s.id = t.assignee_staff_id
left join public.regulation_updates u on u.id = t.regulation_update_id
left join public.compliance_records r on r.id = t.compliance_record_id
left join public.compliance_requirements q on q.id = r.requirement_id
left join lateral (select m.* from public.agent_messages m where m.audit_task_id = t.id order by m.sent_at desc limit 1) lm on true;
grant select on public.v_audit_tasks to authenticated;

drop view if exists public.v_agent_feed;
create view public.v_agent_feed with (security_invoker = on) as
select e.id, e.centre_id, e.agent, e.task_id, e.staff_id, e.kind, e.state, e.summary, e.detail, e.demo, e.created_at,
       s.full_name as staff_name, ct.code as type_code, ct.name as type_name,
       t.state as task_state, t.priority as task_priority, t.next_follow_up,
       e.checklist_item_id, ci.title as item_title, e.audit_task_id, at.state as audit_task_state, at.kind as audit_task_kind,
       e.regulation_update_id, ru.title as update_title
from public.agent_events e
left join public.staff s on s.id = e.staff_id
left join public.certificate_types ct on ct.id = e.certificate_type_id
left join public.credential_tasks t on t.id = e.task_id
left join public.checklist_items ci on ci.id = e.checklist_item_id
left join public.audit_tasks at on at.id = e.audit_task_id
left join public.regulation_updates ru on ru.id = e.regulation_update_id;
grant select on public.v_agent_feed to authenticated;

-- ============================================================================
-- supabase/migrations/20261030090000_integration.sql
-- ============================================================================
-- beehive: one system
-- Joins the staff compliance agent, the audit-readiness agent and the compliance assistant so they share one set
-- of records and one history:
--   1. Any change to the shared records (credentials, certificate uploads, evidence, compliance tasks, medical
--      updates, incidents, child records, regulation updates) re-checks the audit requirements in the same
--      transaction. Requirement status, readiness, audit tasks and the activity feed never wait for a later run,
--      and a status change records what caused it (for example the credential that was renewed).
--   2. Regulation decisions that need action on a requirement checked from beehive's own records (credentials,
--      medical, incidents, children) become an owner action routed to that workflow, closed by the owner.
--   3. The compliance assistant (Gemini) no longer runs a second reminder system: it won't draft a reminder the
--      staff agent is already sending, an approved draft is sent through the staff agent's renewal (same message
--      history, same follow-up schedule), and its escalations go onto the staff agent's renewal task.
--   4. The old expiry check runs the staff agent instead of its own reminder table.

-- ---------------------------------------------------------------------------
-- 1. re-check requirements whenever the shared records change
-- ---------------------------------------------------------------------------
create or replace function public._audit_refresh(p_centre uuid, p_cause text default 'change', p_detail jsonb default '{}')
returns void language plpgsql security definer set search_path = public as $$
declare v_key text;
begin
  if p_centre is null then return; end if;
  if not exists (select 1 from checklist_items where centre_id = p_centre and is_active and approved_at is not null) then return; end if;
  -- once per transaction is enough: deferred triggers run after every change in it
  v_key := 'beehive.refreshed_' || replace(p_centre::text, '-', '');
  if coalesce(current_setting(v_key, true), '') = '1' then return; end if;
  perform set_config(v_key, '1', true);
  perform run_audit_agent_for(p_centre, left(p_cause, 120));
  -- say what caused the changes this transaction recorded
  update agent_events set detail = detail || jsonb_build_object('cause', p_cause) || coalesce(p_detail - 'staff_id' - 'certificate_type_id', '{}'),
         staff_id = coalesce(staff_id, nullif(p_detail->>'staff_id', '')::uuid),
         certificate_type_id = coalesce(certificate_type_id, nullif(p_detail->>'certificate_type_id', '')::uuid)
   where centre_id = p_centre and agent = 'audit' and created_at = now() and kind in ('status_changed', 'resolved', 'gap_detected')
     and not (detail ? 'cause');
end $$;
revoke execute on function public._audit_refresh(uuid, text, jsonb) from public, anon, authenticated;

create or replace function public._refresh_on_change()
returns trigger language plpgsql security definer set search_path = public as $$
declare v_centre uuid; v_cause text; v_detail jsonb := '{}'; r record; v_name text; v_type text;
begin
  if tg_table_name = 'staff_certificates' then
    select s.centre_id as centre_id, s.full_name as staff_name, ct.name as type_name, s.id as staff_id, ct.id as type_id into r
      from staff s join certificate_types ct on ct.id = coalesce(new.certificate_type_id, old.certificate_type_id)
     where s.id = coalesce(new.staff_id, old.staff_id);
    v_centre := r.centre_id;
    v_cause := r.staff_name || '’s ' || r.type_name || case when tg_op = 'DELETE' then ' was removed'
               when new.expiry_date is not null then ' is now valid until ' || _fmt_date(new.expiry_date) else ' was updated' end;
    v_detail := jsonb_build_object('staff_id', r.staff_id, 'certificate_type_id', r.type_id, 'credential', r.type_name, 'staff', r.staff_name);
  elsif tg_table_name = 'certificate_submissions' then
    if tg_op = 'UPDATE' and new.status is not distinct from old.status then return null; end if;
    select s.full_name, ct.name into v_name, v_type from staff s, certificate_types ct where s.id = new.staff_id and ct.id = new.certificate_type_id;
    v_centre := new.centre_id;
    v_cause := v_name || '’s ' || v_type || case new.status when 'pending' then ' renewal was uploaded' when 'approved' then ' was verified' else ' upload was rejected' end;
    v_detail := jsonb_build_object('staff_id', new.staff_id, 'certificate_type_id', new.certificate_type_id, 'credential', v_type, 'staff', v_name);
  elsif tg_table_name = 'evidence' then
    v_centre := coalesce(new.centre_id, old.centre_id); v_cause := 'Evidence changed';
  elsif tg_table_name = 'compliance_records' then
    v_centre := coalesce(new.centre_id, old.centre_id); v_cause := 'Compliance task updated';
  elsif tg_table_name = 'medical_updates' then
    v_centre := new.centre_id; v_cause := 'Medical update ' || coalesce(new.status::text, 'changed');
  elsif tg_table_name = 'incidents' then
    v_centre := new.centre_id; v_cause := 'Incident record updated';
  elsif tg_table_name = 'children' then
    v_centre := coalesce(new.centre_id, old.centre_id); v_cause := 'Child records updated';
  elsif tg_table_name = 'regulation_updates' then
    v_centre := new.centre_id; v_cause := 'Regulation update: ' || new.title;
  end if;
  perform _audit_refresh(v_centre, v_cause, v_detail);
  return null;
end $$;

do $$
declare t text;
begin
  foreach t in array array['staff_certificates', 'certificate_submissions', 'evidence', 'compliance_records', 'medical_updates', 'incidents', 'children'] loop
    execute format('drop trigger if exists zz_refresh_audit on public.%I', t);
    execute format('create constraint trigger zz_refresh_audit after insert or update%s on public.%I deferrable initially deferred for each row execute function public._refresh_on_change()',
                   case when t in ('staff_certificates', 'evidence', 'children') then ' or delete' else '' end, t);
  end loop;
  drop trigger if exists zz_refresh_audit on public.regulation_updates;
  create constraint trigger zz_refresh_audit after insert on public.regulation_updates deferrable initially deferred for each row execute function public._refresh_on_change();
end $$;

-- ---------------------------------------------------------------------------
-- 2. regulation decisions on requirements checked from beehive's own records
-- ---------------------------------------------------------------------------
do $$
declare c text;
begin
  select conname into c from pg_constraint where conrelid = 'public.audit_tasks'::regclass and contype = 'c' and pg_get_constraintdef(oid) ilike '%kind%';
  if c is not null then execute 'alter table public.audit_tasks drop constraint ' || quote_ident(c); end if;
  alter table public.audit_tasks add constraint audit_tasks_kind_check check (kind in ('evidence', 'regulation_review', 'overdue_task', 'owner_action', 'regulation_action'));
end $$;
create unique index if not exists audit_tasks_open_reg_action on public.audit_tasks (regulation_update_id, checklist_item_id) where state <> 'resolved' and kind = 'regulation_action';

create or replace function public.decide_regulation_review(p_review uuid, p_decision text, p_note text default '')
returns jsonb language plpgsql security definer set search_path = public as $$
declare rr regulation_reviews; u regulation_updates; ci checklist_items; t audit_tasks; v_open int;
begin
  if not is_leader() then raise exception 'Only the owner or director can record this decision'; end if;
  if p_decision not in ('no_change', 'update_needed', 'not_applicable') then raise exception 'Unknown decision'; end if;
  select * into rr from regulation_reviews where id = p_review and centre_id = my_centre_id() for update;
  if rr.id is null then raise exception 'Review not found'; end if;
  if rr.decision is not null then raise exception 'You already recorded a decision for this.'; end if;
  select * into u from regulation_updates where id = rr.regulation_update_id;
  select * into ci from checklist_items where id = rr.checklist_item_id;
  update regulation_reviews set decision = p_decision, note = coalesce(p_note, ''), decided_by = auth.uid(), decided_at = now(),
    completed_at = case when p_decision = 'update_needed' then null else now() end where id = rr.id;
  update audit_tasks set state = 'resolved', resolved_at = now(), updated_at = now(),
    resolution = case p_decision when 'no_change' then 'Reviewed: no change needed' when 'not_applicable' then 'Doesn’t apply to this centre' else 'Change needed' end
   where regulation_update_id = u.id and kind = 'regulation_review' and state <> 'resolved' and checklist_item_id is not distinct from rr.checklist_item_id;
  if ci.id is not null then
    if p_decision = 'update_needed' then
      update checklist_items set review_note = 'Update needed after “' || u.title || '”' where id = ci.id;
      if ci.evidence_kind = 'document' then
        -- a policy or record to update: the evidence workflow (upload, check, verify)
        select * into t from audit_tasks where checklist_item_id = ci.id and kind = 'evidence' and state <> 'resolved';
        if t.id is null then
          insert into audit_tasks (centre_id, checklist_item_id, kind, title, reason, recommended_action, priority, state, due_date, regulation_update_id)
          values (ci.centre_id, ci.id, 'evidence', 'Update ' || ci.title, 'You decided the policy needs updating after “' || u.title || '”.',
                  'Update the policy, upload it and verify it. The requirement stays under review until then.', 'medium', 'waiting', current_date + 30, u.id);
        end if;
      else
        -- checked from beehive's own records: an owner action in the workflow that owns those records
        insert into audit_tasks (centre_id, checklist_item_id, kind, title, reason, recommended_action, priority, state, due_date, regulation_update_id)
        values (ci.centre_id, ci.id, 'regulation_action', 'Put “' || u.title || '” into practice: ' || ci.title,
                'You decided practices need to change after “' || u.title || '”.',
                case ci.evidence_kind
                  when 'certificates' then 'Check the staff register against the new requirement in Staff certifications. Renewals and new certificates go through beehive’s staff agent. Mark this done when the change is in place.'
                  when 'medical' then 'Update how medical information is collected and ask families for anything new through beehive. Mark this done when the change is in place.'
                  when 'incidents' then 'Update the incident procedure and brief staff. Mark this done when the change is in place.'
                  else 'Make the change, then mark this done.' end,
                'medium', 'waiting', current_date + 30, u.id)
        on conflict do nothing;
      end if;
    elsif not exists (select 1 from regulation_reviews x where x.checklist_item_id = ci.id and x.id <> rr.id and (x.decision is null or (x.decision = 'update_needed' and x.completed_at is null))) then
      update checklist_items set review_required = false, review_note = '', last_reviewed_at = case when p_decision = 'no_change' then now() else last_reviewed_at end,
             reviewed_by = case when p_decision = 'no_change' then auth.uid() else reviewed_by end
       where id = ci.id;
    end if;
  end if;
  perform log_audit(u.centre_id, 'regulation_update.decision', 'regulation_reviews', rr.id::text,
    jsonb_build_object('update', u.title, 'item', ci.title, 'decision', p_decision, 'note', p_note));
  perform _audit_event(u.centre_id, ci.id, null, u.id, 'regulation_decision', case when p_decision = 'update_needed' then 'Waiting' else 'Resolved' end,
    case p_decision when 'no_change' then 'You confirmed no change needed: ' when 'not_applicable' then 'You marked as not applicable: ' else 'You decided a change is needed: ' end || coalesce(ci.title, u.title),
    jsonb_build_object('decision', p_decision, 'note', p_note, 'update', u.title));
  select count(*) into v_open from regulation_reviews where regulation_update_id = u.id and decision is null;
  if v_open = 0 then
    update regulation_updates set status = 'reviewed', reviewed_at = now() where id = u.id;
    perform _audit_event(u.centre_id, null, null, u.id, 'regulation_reviewed', 'Resolved', 'Regulation review recorded: ' || u.title, '{}');
  end if;
  perform run_audit_agent_for(u.centre_id, 'regulation_decision');
  return jsonb_build_object('decision', p_decision, 'update_status', case when v_open = 0 then 'reviewed' else 'assessed' end);
end $$;
grant execute on function public.decide_regulation_review(uuid, text, text) to authenticated;

-- The owner confirms the change a regulation decision called for is in place.
create or replace function public.complete_audit_task(p_task uuid, p_note text default '')
returns jsonb language plpgsql security definer set search_path = public as $$
declare t audit_tasks; ci checklist_items; u regulation_updates;
begin
  if not is_leader() then raise exception 'Only the owner or director can do this'; end if;
  select * into t from audit_tasks where id = p_task and centre_id = my_centre_id() for update;
  if t.id is null then raise exception 'Task not found'; end if;
  if t.state = 'resolved' then raise exception 'This task is already complete.'; end if;
  if t.kind <> 'regulation_action' then raise exception 'This task closes by itself once the records show it’s done.'; end if;
  select * into ci from checklist_items where id = t.checklist_item_id;
  select * into u from regulation_updates where id = t.regulation_update_id;
  update audit_tasks set state = 'resolved', resolved_at = now(), updated_at = now(), resolution = 'Done' || case when coalesce(trim(p_note), '') <> '' then ': ' || trim(p_note) else '' end where id = t.id;
  update regulation_reviews set completed_at = now(), note = case when coalesce(trim(p_note), '') <> '' then trim(note || ' ' || trim(p_note)) else note end
   where regulation_update_id = t.regulation_update_id and checklist_item_id is not distinct from t.checklist_item_id and decision = 'update_needed' and completed_at is null;
  if ci.id is not null and not exists (select 1 from regulation_reviews rr where rr.checklist_item_id = ci.id and (rr.decision is null or (rr.decision = 'update_needed' and rr.completed_at is null))) then
    update checklist_items set review_required = false, review_note = '', last_reviewed_at = now(), reviewed_by = auth.uid() where id = ci.id;
  end if;
  perform log_audit(t.centre_id, 'audit_task.completed', 'audit_tasks', t.id::text, jsonb_build_object('note', p_note, 'update', u.title));
  perform _audit_event(t.centre_id, t.checklist_item_id, t.id, t.regulation_update_id, 'regulation_action_done', 'Resolved',
    'You put “' || coalesce(u.title, 'the change') || '” into practice: ' || coalesce(ci.title, ''), jsonb_build_object('note', p_note));
  perform run_audit_agent_for(t.centre_id, 'regulation_action');
  return jsonb_build_object('done', true);
end $$;
grant execute on function public.complete_audit_task(uuid, text) to authenticated;

-- ---------------------------------------------------------------------------
-- 3. the compliance assistant works through the staff agent's renewals
-- ---------------------------------------------------------------------------
-- The assistant's credential review also sees the staff agent's messages, so it knows what was already sent.
create or replace function public._credential_review(p_centre uuid)
returns table (staff_id uuid, staff_name text, room text, has_login boolean, certificate_code text, certificate_name text,
               status text, expiry_date date, days_left int, reminder_window int,
               last_reminder_sent date, renewal_submitted boolean, open_draft boolean, escalation_open boolean, follow_up_due boolean)
language sql stable security definer set search_path = public as $$
  select s.id, s.full_name, coalesce(nullif(s.room, ''), '—'), s.user_id is not null, ct.code, ct.name,
         case when sc.id is null then 'missing'
              when not ct.expires or sc.expiry_date is null then 'valid'
              when sc.expiry_date < current_date then 'expired'
              when sc.expiry_date <= current_date + ct.reminder_days then 'expiring_soon'
              else 'valid' end,
         sc.expiry_date,
         case when sc.expiry_date is null then null else sc.expiry_date - current_date end,
         ct.reminder_days,
         greatest((select max(r.sent_at)::date from reminders r where r.staff_certificate_id = sc.id and r.status = 'sent'),
                  (select max(d.decided_at)::date from staff_reminder_drafts d where d.staff_id = s.id and d.certificate_type_id = ct.id and d.status = 'sent'),
                  (select max(m.sent_at)::date from agent_messages m join credential_tasks t on t.id = m.task_id where t.staff_id = s.id and t.certificate_type_id = ct.id)),
         exists (select 1 from certificate_submissions cs where cs.staff_id = s.id and cs.certificate_type_id = ct.id and cs.status = 'pending'),
         exists (select 1 from staff_reminder_drafts d where d.staff_id = s.id and d.certificate_type_id = ct.id and d.status = 'draft' and d.kind <> 'escalation'),
         exists (select 1 from staff_reminder_drafts d where d.staff_id = s.id and d.certificate_type_id = ct.id and d.status = 'draft' and d.kind = 'escalation')
           or exists (select 1 from credential_tasks t where t.staff_id = s.id and t.certificate_type_id = ct.id and t.state <> 'resolved' and t.escalated_at is not null and t.escalation_ack_at is null),
         exists (select 1 from credential_tasks t where t.staff_id = s.id and t.certificate_type_id = ct.id and t.state <> 'resolved' and t.next_follow_up <= current_date)
  from staff s
  cross join certificate_types ct
  left join lateral (select x.* from staff_certificates x where x.staff_id = s.id and x.certificate_type_id = ct.id
                     order by x.expiry_date desc nulls last limit 1) sc on true
  where s.centre_id = p_centre and s.is_active and ct.code = any (_required_cert_codes())
    and s.position not ilike '%owner%';
$$;
revoke execute on function public._credential_review(uuid) from public, anon, authenticated;

create or replace function public.agent_save_reminder_drafts(p_key text, p_drafts jsonb)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_centre uuid := _agent_centre(p_key);
  d jsonb; v_staff staff; v_type certificate_types; v_rev record; v_body text; v_kind text; v_prio text; v_days int; v_ct credential_tasks;
  v_saved jsonb := '[]'::jsonb; v_skipped jsonb := '[]'::jsonb; v_id uuid; v_n int;
begin
  if jsonb_typeof(p_drafts) <> 'array' then raise exception 'drafts must be a list'; end if;
  if jsonb_array_length(p_drafts) > 15 then raise exception 'At most 15 drafts per run'; end if;
  for d in select * from jsonb_array_elements(p_drafts) loop
    v_body := trim(coalesce(d->>'body', ''));
    v_kind := coalesce(d->>'kind', 'renewal');
    v_prio := coalesce(d->>'priority', 'medium');
    v_days := coalesce(nullif(d->>'follow_up_in_days', '')::int, 7);
    select count(*) into v_n from staff where centre_id = v_centre and is_active and lower(full_name) = lower(trim(d->>'staff'));
    if v_n <> 1 then v_skipped := v_skipped || jsonb_build_object('staff', d->>'staff', 'reason', 'No single active educator with that exact name'); continue; end if;
    select * into v_staff from staff where centre_id = v_centre and is_active and lower(full_name) = lower(trim(d->>'staff'));
    select * into v_type from certificate_types where code = upper(replace(trim(coalesce(d->>'certificate', '')), ' ', '_'));
    if v_type.id is null or not (v_type.code = any (_required_cert_codes())) then
      v_skipped := v_skipped || jsonb_build_object('staff', v_staff.full_name, 'reason', 'Unknown or not-required certificate'); continue; end if;
    select * into v_rev from _credential_review(v_centre) r where r.staff_id = v_staff.id and r.certificate_code = v_type.code;
    if v_rev.status = 'valid' then
      v_skipped := v_skipped || jsonb_build_object('staff', v_staff.full_name, 'certificate', v_type.code, 'reason', 'Certificate is current; no reminder needed'); continue; end if;
    if v_rev.renewal_submitted then
      v_skipped := v_skipped || jsonb_build_object('staff', v_staff.full_name, 'certificate', v_type.code, 'reason', 'Renewal already submitted; the owner must review it'); continue; end if;
    if v_rev.open_draft then
      v_skipped := v_skipped || jsonb_build_object('staff', v_staff.full_name, 'certificate', v_type.code, 'reason', 'A draft is already waiting for approval'); continue; end if;
    -- one reminder system: the staff agent is already chasing this renewal
    select * into v_ct from credential_tasks where staff_id = v_staff.id and certificate_type_id = v_type.id and state <> 'resolved';
    if v_ct.id is not null and v_ct.requests_sent > 0 then
      v_skipped := v_skipped || jsonb_build_object('staff', v_staff.full_name, 'certificate', v_type.code,
        'reason', 'beehive’s staff agent already asked ' || split_part(v_staff.full_name, ' ', 1) || ' on ' || _fmt_date(v_ct.last_request_at::date) ||
                  case when v_ct.next_follow_up is not null then ' and follows up on ' || _fmt_date(v_ct.next_follow_up) else '' end || '. No second reminder needed.');
      continue;
    end if;
    if v_kind not in ('renewal', 'missing', 'follow_up') then v_kind := 'renewal'; end if;
    if v_prio not in ('high', 'medium', 'low') then v_prio := 'medium'; end if;
    if length(v_body) < 20 or length(v_body) > 900 then
      v_skipped := v_skipped || jsonb_build_object('staff', v_staff.full_name, 'reason', 'Message must be 20 to 900 characters'); continue; end if;
    if v_days < 1 or v_days > 30 then v_days := 7; end if;
    insert into staff_reminder_drafts (centre_id, staff_id, certificate_type_id, kind, priority, reason, body, follow_up_on)
    values (v_centre, v_staff.id, v_type.id, v_kind, v_prio, left(coalesce(d->>'reason', ''), 300), v_body, current_date + v_days)
    returning id into v_id;
    perform log_audit(v_centre, 'agent.reminder_drafted', 'staff_reminder_drafts', v_id::text,
      jsonb_build_object('staff_id', v_staff.id, 'certificate', v_type.code, 'kind', v_kind, 'by', 'Beehive Compliance Agent'));
    v_saved := v_saved || jsonb_build_object('staff', v_staff.full_name, 'certificate', v_type.code, 'draft_id', v_id, 'follow_up_on', current_date + v_days);
  end loop;
  return jsonb_build_object('saved', v_saved, 'skipped', v_skipped,
    'note', 'Saved as drafts. Nothing has been sent. The owner approves each reminder in Beehive; approved reminders go out through the staff agent’s renewal.');
end $$;
grant execute on function public.agent_save_reminder_drafts(text, jsonb) to anon, authenticated;

-- Escalations go onto the staff agent's renewal task, so the owner sees one escalation per renewal.
create or replace function public.agent_flag_for_owner(p_key text, p_items jsonb)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_centre uuid := _agent_centre(p_key); d jsonb; v_staff staff; v_type uuid; v_id uuid; v_out jsonb := '[]'::jsonb; v_skip jsonb := '[]'::jsonb; v_n int;
        v_ct credential_tasks; v_reason text;
begin
  if jsonb_typeof(p_items) <> 'array' then raise exception 'items must be a list'; end if;
  if jsonb_array_length(p_items) > 15 then raise exception 'At most 15 escalations per run'; end if;
  for d in select * from jsonb_array_elements(p_items) loop
    select count(*) into v_n from staff where centre_id = v_centre and is_active and lower(full_name) = lower(trim(d->>'staff'));
    if v_n <> 1 then continue; end if;
    select * into v_staff from staff where centre_id = v_centre and is_active and lower(full_name) = lower(trim(d->>'staff'));
    select id into v_type from certificate_types where code = upper(replace(trim(coalesce(d->>'certificate', '')), ' ', '_'));
    v_reason := left(coalesce(d->>'reason', 'Needs the owner’s decision'), 300);
    select * into v_ct from credential_tasks where staff_id = v_staff.id and certificate_type_id = v_type and state <> 'resolved';
    if v_ct.id is not null then
      if v_ct.escalated_at is not null and v_ct.escalation_ack_at is null then
        v_skip := v_skip || jsonb_build_object('staff', v_staff.full_name, 'reason', 'Already escalated to the owner on the renewal task');
        continue;
      end if;
      perform _escalate(v_ct.id, v_reason, 'Review the compliance assistant’s concern and decide the next step.');
      v_out := v_out || jsonb_build_object('staff', v_staff.full_name, 'escalation_id', v_ct.id, 'routed_to', 'staff_agent');
      continue;
    end if;
    if exists (select 1 from staff_reminder_drafts x where x.staff_id = v_staff.id and x.kind = 'escalation' and x.status = 'draft'
               and x.certificate_type_id is not distinct from v_type) then continue; end if;
    insert into staff_reminder_drafts (centre_id, staff_id, certificate_type_id, kind, priority, reason)
    values (v_centre, v_staff.id, v_type, 'escalation', 'high', v_reason)
    returning id into v_id;
    perform log_audit(v_centre, 'agent.escalated', 'staff_reminder_drafts', v_id::text,
      jsonb_build_object('staff_id', v_staff.id, 'reason', d->>'reason', 'by', 'Beehive Compliance Agent'));
    v_out := v_out || jsonb_build_object('staff', v_staff.full_name, 'escalation_id', v_id, 'routed_to', 'compliance_page');
  end loop;
  return jsonb_build_object('escalated', v_out, 'skipped', v_skip, 'note', 'Flagged for the owner. The agent has not contacted anyone.');
end $$;
grant execute on function public.agent_flag_for_owner(text, jsonb) to anon, authenticated;

-- An approved draft is sent through the staff agent's renewal: same message history, same follow-up schedule.
create or replace function public.approve_staff_reminder(p_id uuid, p_body text default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_d staff_reminder_drafts; v_cert uuid; v_ct credential_tasks; s staff; ct certificate_types; v_exp date; v_channel text; v_to text; v_next date; v_msg uuid; v_body text;
begin
  if not is_leader() then raise exception 'Only the owner or director can approve reminders'; end if;
  select * into v_d from staff_reminder_drafts where id = p_id and centre_id = my_centre_id();
  if not found then raise exception 'Reminder not found'; end if;
  if v_d.status <> 'draft' or v_d.kind = 'escalation' then raise exception 'This reminder has already been handled'; end if;
  select * into v_ct from credential_tasks where staff_id = v_d.staff_id and certificate_type_id = v_d.certificate_type_id and state <> 'resolved';
  if v_ct.id is not null and v_ct.requests_sent > 0 and v_ct.last_request_at > now() - interval '1 day' then
    raise exception 'beehive’s staff agent already sent this reminder today. Discard the draft.';
  end if;
  v_body := coalesce(nullif(trim(p_body), ''), v_d.body);
  update staff_reminder_drafts set status = 'sent', body = v_body, decided_by = auth.uid(), decided_at = now() where id = p_id;
  select * into s from staff where id = v_d.staff_id;
  select * into ct from certificate_types where id = v_d.certificate_type_id;
  select id, expiry_date into v_cert, v_exp from staff_certificates where staff_id = v_d.staff_id and certificate_type_id = v_d.certificate_type_id
   order by expiry_date desc nulls last limit 1;
  if v_ct.id is null then
    insert into credential_tasks (centre_id, staff_id, certificate_type_id, priority, state, reason, expiry_date)
    values (v_d.centre_id, v_d.staff_id, v_d.certificate_type_id, cert_priority(coalesce(v_exp - current_date, -1), v_exp is null), 'waiting',
            case when v_exp is null then 'No ' || ct.name || ' on file' else 'Expires ' || _fmt_date(v_exp) end, v_exp)
    returning * into v_ct;
    perform _agent_event(v_d.centre_id, v_ct.id, v_d.staff_id, v_d.certificate_type_id, 'detected', 'Monitoring', 'Renewal opened from the compliance assistant',
      jsonb_build_object('priority', v_ct.priority, 'reason', v_ct.reason));
  end if;
  if coalesce(s.email, '') <> '' then v_channel := 'email'; v_to := s.email; elsif coalesce(s.phone, '') <> '' then v_channel := 'sms'; v_to := s.phone; else v_channel := 'none'; v_to := ''; end if;
  v_next := coalesce(v_d.follow_up_on, current_date + _follow_up_days(v_ct.priority));
  insert into agent_messages (centre_id, task_id, staff_id, kind, channel, recipient, subject, body, upload_link, outcome, next_follow_up)
  values (v_d.centre_id, v_ct.id, v_d.staff_id, case when v_ct.requests_sent = 0 then 'request' else 'follow_up' end, v_channel, v_to,
          'Please renew your ' || ct.name, v_body, '/#upload/' || v_ct.upload_token, case when v_channel = 'none' then 'no_contact' else 'simulated' end, v_next)
  returning id into v_msg;
  update credential_tasks set requests_sent = requests_sent + 1, last_request_at = now(), next_follow_up = v_next, updated_at = now(),
         state = case when state = 'owner_review' then state else 'waiting' end where id = v_ct.id;
  perform _agent_event(v_d.centre_id, v_ct.id, v_d.staff_id, v_d.certificate_type_id, case when v_ct.requests_sent = 0 then 'request_sent' else 'follow_up_sent' end, 'Action taken',
    'Reminder approved by you and sent', jsonb_build_object('message_id', v_msg, 'channel', v_channel, 'recipient', v_to, 'simulated', true, 'next_follow_up', v_next, 'source', 'compliance_assistant'));
  if v_cert is not null then
    insert into reminders (staff_certificate_id, channel, send_at, status, sent_at) values (v_cert, 'in_app', now(), 'sent', now());
  end if;
  perform log_audit(v_d.centre_id, 'staff_reminder.sent', 'staff_reminder_drafts', p_id::text,
    jsonb_build_object('staff_id', v_d.staff_id, 'drafted_by_agent', v_d.created_by = 'agent', 'follow_up_on', v_next, 'credential_task_id', v_ct.id));
  return jsonb_build_object('sent', true, 'follow_up_on', v_next, 'credential_task_id', v_ct.id);
end $$;
grant execute on function public.approve_staff_reminder(uuid, text) to authenticated;

-- ---------------------------------------------------------------------------
-- 4. the old expiry check runs the staff agent
-- ---------------------------------------------------------------------------
create or replace function public.run_expiry_check()
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_centre uuid := my_centre_id(); r jsonb; v_staff int;
begin
  if not is_leader() then raise exception 'Only the owner or director can run the expiry check'; end if;
  r := run_staff_agent_for(v_centre, 'expiry_check');
  select count(distinct m.staff_id) into v_staff from agent_messages m where m.centre_id = v_centre and m.sent_at = now();
  perform log_audit(v_centre, 'reminders.expiry_check', 'credential_tasks', v_centre::text, r);
  return jsonb_build_object('sent', coalesce((r->>'requests')::int, 0) + coalesce((r->>'follow_ups')::int, 0), 'staff', v_staff, 'agent', r);
end $$;
grant execute on function public.run_expiry_check() to authenticated;

-- ============================================================================
-- supabase/migrations/20261031090000_ask_beehive.sql
-- ============================================================================
-- beehive: read-only data for "Ask beehive" (Gemini, server-side at /api/ask)
-- The assistant answers from the same records every page uses. These functions only read, are scoped to one
-- centre by its agent key, and leave out children's medical details.

-- Everything the owner sees on the Overview, in one read.
create or replace function public.agent_overview(p_key text)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare v_centre uuid := _agent_centre(p_key);
begin
  return jsonb_build_object(
    'centre', (select name from centres where id = v_centre),
    'today', to_char(_local_today(), 'DD Mon YYYY'),
    'checklist_approved', exists (select 1 from checklist_items where centre_id = v_centre and is_active and approved_at is not null),
    'readiness', (select jsonb_build_object('score_percent', r.score, 'compliant', r.green, 'under_review', r.yellow, 'missing', r.red, 'requirements', r.total_items,
                    'method', 'compliant counts 1, under review 0.5, missing 0, divided by approved requirements')
                  from v_readiness r where r.centre_id = v_centre),
    'requirements', coalesce((select jsonb_agg(jsonb_build_object(
                      'title', c.title, 'area', c.area, 'status', c.req_status, 'priority', c.priority, 'flags', c.flags,
                      'why_this_status', c.reason, 'why_it_matters', c.why, 'priority_reason', c.priority_reason,
                      'next_action', c.next_action, 'regulation', c.source_ref, 'required_evidence', c.evidence_hint)
                      order by case c.priority when 'critical' then 0 when 'high' then 1 when 'medium' then 2 else 3 end, c.area, c.title)
                    from v_checklist_status c where c.centre_id = v_centre and c.approved), '[]'::jsonb),
    'staff_renewals', coalesce((select jsonb_agg(jsonb_build_object(
                      'staff', t.staff_name, 'credential', t.type_name, 'priority', t.priority, 'state', t.state, 'reason', t.reason,
                      'requests_sent', t.requests_sent, 'next_follow_up', t.next_follow_up,
                      'escalated', t.escalated_at is not null and t.escalation_ack_at is null, 'escalation_reason', t.escalation_reason,
                      'recommended_action', t.recommended_action, 'upload_waiting_for_owner', t.pending_submission_id is not null)
                      order by case t.priority when 'critical' then 0 when 'high' then 1 when 'medium' then 2 else 3 end, t.days_left nulls first)
                    from v_credential_tasks t where t.centre_id = v_centre and t.state <> 'resolved'), '[]'::jsonb),
    'audit_tasks', coalesce((select jsonb_agg(jsonb_build_object(
                      'task', a.title, 'kind', a.kind, 'state', a.state, 'priority', a.priority, 'assigned_to', coalesce(a.assignee_name, 'the owner'),
                      'next_follow_up', a.next_follow_up, 'recommended', a.recommended_action))
                    from v_audit_tasks a where a.centre_id = v_centre and a.state <> 'resolved'), '[]'::jsonb),
    'regulation_updates', coalesce((select jsonb_agg(jsonb_build_object(
                      'title', u.title, 'status', u.status, 'summary', u.summary, 'assessment', u.assessment,
                      'reviews', (select coalesce(jsonb_agg(jsonb_build_object('requirement', ci.title, 'impact', rr.impact, 'decision', rr.decision,
                                    'change_in_place', rr.completed_at is not null)), '[]'::jsonb)
                                  from regulation_reviews rr left join checklist_items ci on ci.id = rr.checklist_item_id where rr.regulation_update_id = u.id)))
                    from regulation_updates u where u.centre_id = v_centre), '[]'::jsonb),
    'compliance_tasks', agent_compliance_tasks(p_key),
    'waiting_for_owner', jsonb_build_object(
      'certificates_to_verify', (select count(*) from certificate_submissions where centre_id = v_centre and status = 'pending'),
      'evidence_to_verify', (select count(*) from evidence where centre_id = v_centre and status = 'pending'),
      'regulation_decisions', (select count(*) from regulation_reviews where centre_id = v_centre and decision is null),
      'escalations', (select count(*) from credential_tasks where centre_id = v_centre and state <> 'resolved' and escalated_at is not null and escalation_ack_at is null),
      'medical_updates_to_review', (select count(*) from medical_updates where centre_id = v_centre and status = 'pending'))
  );
end $$;
grant execute on function public.agent_overview(text) to anon, authenticated;

-- Official guidance: Ask beehive uses agent_guidance(p_key, p_topic) from 20261026090000_compliance_library.sql.

-- ============================================================================
-- supabase/seed_demo.sql
-- ============================================================================
-- ============================================================================
-- Beehive demo data (matches the people and records in beehive-demo/)
-- Run in Supabase → SQL Editor AFTER all files in supabase/migrations.
-- Safe to re-run: it deletes and recreates the demo centre and demo logins.
--
-- Demo logins (password for all: Beehive2026!)
--   sara@beehive.demo   – Sara Williams, centre owner
--   priya@beehive.demo  – Priya Patel, parent of Maya Patel
--   mia@beehive.demo    – Mia Chen, lead educator
--
-- Not included on purpose: evidence uploads for the audit checklist (added during the demo).
-- Compliance task history is included so the compliance register has realistic dates.
-- After approval, document-based checklist items show "Evidence missing" until real files are uploaded.
-- ============================================================================

do $$
declare
  c_centre uuid := 'b0000000-0000-4000-8000-000000000001';
  u_sara   uuid := 'b0000000-0000-4000-8000-0000000000a1';
  u_priya  uuid := 'b0000000-0000-4000-8000-0000000000a2';
  u_mia    uuid := 'b0000000-0000-4000-8000-0000000000a3';
  v_pw     text;
  v_key    text := 'bh_demo_' || md5(random()::text || clock_timestamp()::text);
  s record;
  v_staff uuid;
  c_maya uuid; c_oscar uuid; c_isla uuid; c_ruby uuid;
begin
  -- ---------- reset previous demo ----------
  alter table public.audit_log disable trigger audit_log_immutable;
  delete from public.centres where id = c_centre;
  alter table public.audit_log enable trigger audit_log_immutable;
  delete from auth.users where email in ('sara@beehive.demo', 'priya@beehive.demo', 'mia@beehive.demo');

  -- ---------- demo logins ----------
  v_pw := extensions.crypt('Beehive2026!', extensions.gen_salt('bf'));
  insert into auth.users (instance_id, id, aud, role, email, encrypted_password, email_confirmed_at,
                          raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
                          confirmation_token, email_change, email_change_token_new, recovery_token)
  values
    ('00000000-0000-0000-0000-000000000000', u_sara,  'authenticated', 'authenticated', 'sara@beehive.demo',  v_pw, now(), '{"provider":"email","providers":["email"]}', '{"full_name":"Sara Williams"}', now(), now(), '', '', '', ''),
    ('00000000-0000-0000-0000-000000000000', u_priya, 'authenticated', 'authenticated', 'priya@beehive.demo', v_pw, now(), '{"provider":"email","providers":["email"]}', '{"full_name":"Priya Patel"}',   now(), now(), '', '', '', ''),
    ('00000000-0000-0000-0000-000000000000', u_mia,   'authenticated', 'authenticated', 'mia@beehive.demo',   v_pw, now(), '{"provider":"email","providers":["email"]}', '{"full_name":"Mia Chen"}',      now(), now(), '', '', '', '');
  insert into auth.identities (id, user_id, provider_id, identity_data, provider, last_sign_in_at, created_at, updated_at)
  select gen_random_uuid(), u.id, u.id::text, jsonb_build_object('sub', u.id::text, 'email', u.email, 'email_verified', true), 'email', now(), now(), now()
  from auth.users u where u.id in (u_sara, u_priya, u_mia);

  -- ---------- centre ----------
  insert into public.centres (id, name, suburb, state, staff_code, family_code)
  values (c_centre, 'Beehive Early Learning', 'Liverpool', 'NSW', 'BEESTF', 'BEEFAM');
  update public.users set centre_id = c_centre, role = 'owner',    full_name = 'Sara Williams', phone = '04 0000 1357' where id = u_sara;
  update public.users set centre_id = c_centre, role = 'parent',   full_name = 'Priya Patel',   phone = '04 0000 2468' where id = u_priya;
  update public.users set centre_id = c_centre, role = 'educator', full_name = 'Mia Chen'      where id = u_mia;
  perform public.seed_compliance_requirements(c_centre);

  -- ---------- compliance history: when each recurring task was last done and when it's next due ----------
  for s in select * from (values
    ('Emergency and evacuation rehearsal',           array[100, 190], -10, 'Fire evacuation, all rooms, 4 min 10 s'),
    ('Playground and premises safety check',         array[5, 12, 19],  2, 'No hazards found'),
    ('Fire equipment service',                       array[140],       40, 'Extinguishers and blankets serviced by contractor'),
    ('Medical conditions policy review',             array[300],       65, 'Reviewed with families of children with action plans'),
    ('Sun protection policy review',                 array[355],       10, 'Checked against ACECQA guidelines'),
    ('Sleep and rest policy review',                 array[210],      155, 'Annual review and risk assessment'),
    ('Quality Improvement Plan review',              array[200],      165, 'QA2 and QA7 goals updated'),
    ('Staff record and responsible person register', array[26, 57],     4, 'Register checked against roster'),
    ('Excursion risk assessments up to date',        array[]::int[],   21, '')
  ) as t(title, done_days, due_in, note) loop
    update public.compliance_records r set due_date = current_date + s.due_in
      from public.compliance_requirements q
     where r.requirement_id = q.id and q.centre_id = c_centre and q.title = s.title and r.status = 'pending';
    insert into public.compliance_records (centre_id, requirement_id, status, due_date, completed_on, completed_by, notes, created_at)
    select c_centre, q.id, 'completed', current_date - d, current_date - d, u_sara, s.note, now() - make_interval(days => d)
      from public.compliance_requirements q, unnest(s.done_days) d
     where q.centre_id = c_centre and q.title = s.title;
  end loop;

  -- ---------- staff and certificates (days from today, as in the prototype) ----------
  insert into public.staff (centre_id, user_id, full_name, email, position, room)
  values (c_centre, u_sara, 'Sara Williams', 'sara@beehive.demo', 'Centre owner', '');

  for s in select * from (values
    ('Mia Chen',      'mia@beehive.demo',   'Lead educator',      'Wattle Room',  597, 30,  30,  195),
    ('Noah Williams', 'noah@example.com',   'Educator',           'Banksia Room', 466, 169, 169, 7),
    ('Ava Patel',     'ava@example.com',    'Educator',           'Gumtree Room', 60,  142, 142, 299),
    ('Luca Martin',   'luca@example.com',   'Assistant educator', 'Wattle Room',  441, -46, 17,  178),
    ('Ella Brooks',   'ella@example.com',   'Educator',           'Banksia Room', 615, 201, 201, 104),
    ('Oliver King',   'oliver@example.com', 'Educator',           'Gumtree Room', 326, 30,  35,  220),
    ('Zara Ali',      'zara@example.com',   'Educator',           'Wattle Room',  534, 60,  48,  86),
    ('Leo Thompson',  'leo@example.com',    'Assistant educator', 'Banksia Room', 286, 107, 20,  107),
    ('Amara Singh',   'amara@example.com',  'Educator',           'Gumtree Room', 7,   192, 192, 202),
    ('Jack Wilson',   'jack@example.com',   'Educator',           'Wattle Room',  453, 88,  88,  233)
  ) as t(name, email, position, room, d_wwcc, d_fa, d_cpr, d_ana) loop
    insert into public.staff (centre_id, user_id, full_name, email, position, room)
    values (c_centre, case when s.email = 'mia@beehive.demo' then u_mia end, s.name, s.email, s.position, s.room)
    returning id into v_staff;
    insert into public.staff_certificates (staff_id, certificate_type_id, certificate_number, issue_date, expiry_date)
    values
      (v_staff, (select id from public.certificate_types where code = 'WWCC'),        'WWC' || (1000000 + floor(random() * 8999999))::int || 'E', current_date + s.d_wwcc - 1825, current_date + s.d_wwcc),
      (v_staff, (select id from public.certificate_types where code = 'FIRST_AID'),   'HLTAID012', current_date + s.d_fa - 1095,  current_date + s.d_fa),
      (v_staff, (select id from public.certificate_types where code = 'CPR'),         'HLTAID009', current_date + s.d_cpr - 365,  current_date + s.d_cpr),
      (v_staff, (select id from public.certificate_types where code = 'ANAPHYLAXIS'), '22578VIC',  current_date + s.d_ana - 1095, current_date + s.d_ana);
  end loop;

  -- Renewal prompts already sent for Mia (30 days) and Noah (7 days), as shown in the prototype.
  update public.reminders r set status = 'sent', sent_at = now() - interval '1 hour'
  from public.staff_certificates sc join public.staff st on st.id = sc.staff_id
  where r.staff_certificate_id = sc.id and st.centre_id = c_centre and r.status = 'scheduled'
    and ((st.full_name = 'Mia Chen' and r.window_days = 30) or (st.full_name = 'Noah Williams' and r.window_days = 7));

  -- ---------- staff compliance agent: contact details and a few days of history ----------
  -- Phone numbers are invented. Leo has no email, so the agent texts him (simulated SMS).
  update public.staff set phone = '04 0000 ' || lpad((1000 + x.rn)::text, 4, '0')
    from (select id as sid, row_number() over (order by full_name) as rn from public.staff where centre_id = c_centre) x
   where id = x.sid;
  update public.staff set email = '' where centre_id = c_centre and full_name = 'Leo Thompson';
  -- Jack never supplied his anaphylaxis training (missing = critical).
  delete from public.staff_certificates sc using public.staff st, public.certificate_types ct
   where sc.staff_id = st.id and sc.certificate_type_id = ct.id and st.centre_id = c_centre and st.full_name = 'Jack Wilson' and ct.code = 'ANAPHYLAXIS';
  -- Oliver's First Aid is the live demo: three days ago it was still 33 days out (Monitor), so the agent only watched it.
  update public.staff_certificates sc set expiry_date = current_date + 33
    from public.staff st, public.certificate_types ct
   where sc.staff_id = st.id and sc.certificate_type_id = ct.id and st.centre_id = c_centre and st.full_name = 'Oliver King' and ct.code = 'FIRST_AID';
  perform public.run_staff_agent_for(c_centre, 'seed');
  update public.staff_certificates sc set expiry_date = current_date + 30
    from public.staff st, public.certificate_types ct
   where sc.staff_id = st.id and sc.certificate_type_id = ct.id and st.centre_id = c_centre and st.full_name = 'Oliver King' and ct.code = 'FIRST_AID';
  -- That run happened three days ago.
  update public.agent_events set created_at = created_at - interval '3 days', demo = true where centre_id = c_centre;
  update public.agent_messages set sent_at = sent_at - interval '3 days', next_follow_up = next_follow_up - 3 where centre_id = c_centre;
  update public.agent_runs set ran_at = ran_at - interval '3 days' where centre_id = c_centre;
  update public.credential_tasks set opened_at = opened_at - interval '3 days', updated_at = updated_at - interval '3 days',
         last_request_at = last_request_at - interval '3 days', next_follow_up = next_follow_up - 3,
         escalated_at = escalated_at - interval '3 days'
   where centre_id = c_centre;
  -- Yesterday Amara uploaded a Working with Children Check through her link, but it's her old one: flagged for Sara.
  perform public._submit_checked(st, ct, 'amara-wwcc.jpg', null, null, 'demo-amara-old-wwcc',
            jsonb_build_object('readable', true, 'name', 'Amara Singh', 'type_code', 'WWCC', 'number', 'WWC0458812E',
                               'issue_date', current_date + 7 - 1825, 'expiry_date', current_date + 7, 'demo', true),
            null, null, 'link', null)
    from public.staff st, public.certificate_types ct
   where st.centre_id = c_centre and st.full_name = 'Amara Singh' and ct.code = 'WWCC';
  update public.certificate_submissions set submitted_at = now() - interval '1 day' where centre_id = c_centre and source = 'link';
  update public.agent_events set created_at = now() - interval '1 day', demo = true where centre_id = c_centre and kind in ('upload_received', 'flagged');

  -- ---------- children (3 rooms) ----------
  insert into public.children (centre_id, first_name, last_name, date_of_birth, room, emergency_contact) values
    (c_centre, 'Maya',   'Patel',    current_date - 1100, 'Banksia Room', 'Priya Patel · 04 0000 2468') returning id into c_maya;
  insert into public.children (centre_id, first_name, last_name, date_of_birth, room, emergency_contact) values
    (c_centre, 'Oscar',  'Nguyen',   current_date - 900,  'Wattle Room',  'Linh Nguyen · 04 0000 3141') returning id into c_oscar;
  insert into public.children (centre_id, first_name, last_name, date_of_birth, room, emergency_contact) values
    (c_centre, 'Isla',   'Brown',    current_date - 1500, 'Gumtree Room', 'Tom Brown · 04 0000 2718') returning id into c_isla;
  insert into public.children (centre_id, first_name, last_name, date_of_birth, room, emergency_contact) values
    (c_centre, 'Ruby',   'Chen',     current_date - 1300, 'Banksia Room', 'Grace Chen · 04 0000 1618') returning id into c_ruby;
  insert into public.children (centre_id, first_name, last_name, date_of_birth, room, emergency_contact) values
    (c_centre, 'Noah',   'Kaur',     current_date - 820,  'Wattle Room',  'Harpreet Kaur · 04 0000 1414'),
    (c_centre, 'Ava',    'Hassan',   current_date - 1010, 'Banksia Room', 'Omar Hassan · 04 0000 1732'),
    (c_centre, 'Leo',    'Petrovic', current_date - 1400, 'Gumtree Room', 'Ana Petrovic · 04 0000 2236'),
    (c_centre, 'Mila',   'Rossi',    current_date - 760,  'Wattle Room',  'Marco Rossi · 04 0000 2645'),
    (c_centre, 'Jayden', 'Smith',    current_date - 1550, 'Gumtree Room', 'Kate Smith · 04 0000 3316'),
    (c_centre, 'Zoe',    'Wilson',   current_date - 1180, 'Banksia Room', 'Ben Wilson · 04 0000 1123'),
    (c_centre, 'Arjun',  'Mehta',    current_date - 980,  'Wattle Room',  'Neha Mehta · 04 0000 1958'),
    (c_centre, 'Sophie', 'Taylor',   current_date - 1450, 'Gumtree Room', 'Emma Taylor · 04 0000 2584');
  insert into public.child_parents (child_id, user_id, relationship) values (c_maya, u_priya, 'Mother');

  -- ---------- medical profiles (already reviewed by the centre) ----------
  insert into public.medical_updates (centre_id, child_id, allergies, conditions, dietary, medications, care_notes, emergency_contact,
                                      signer_name, parent_confirmed, submitted_by, submitted_at, status, approved_by, approved_at)
  values
    (c_centre, c_maya, 'Peanuts', 'Asthma', 'Peanut-free meals', 'Ventolin inhaler (as needed)', 'Please contact me if Maya has breathing symptoms.',
     'Priya Patel · 04 0000 2468', 'Priya Patel', true, u_priya, now() - interval '8 days', 'approved', u_sara, now() - interval '7 days'),
    (c_centre, c_oscar, 'Egg', 'Anaphylaxis', 'Egg-free meals', 'EpiPen Jr 0.15 mg (kept in Wattle Room kit)', 'Action plan on the room wall.',
     'Linh Nguyen · 04 0000 3141', 'Linh Nguyen', true, null, now() - interval '30 days', 'approved', u_sara, now() - interval '29 days'),
    (c_centre, c_isla, 'None', 'None', 'Dairy-free', 'None', 'Prefers a short rest after lunch.',
     'Tom Brown · 04 0000 2718', 'Tom Brown', true, null, now() - interval '60 days', 'approved', u_sara, now() - interval '59 days');
  delete from public.parent_messages where centre_id = c_centre and trigger = 'receipt';  -- no receipts for historic records

  -- ---------- family thread for Maya ----------
  insert into public.parent_messages (centre_id, child_id, trigger, body, status, is_automatic, sent_at)
  values (c_centre, c_maya, 'reminder',
          'Hi Priya, it’s time to review Maya’s medical details. Please check the information in the family portal and send us any changes.',
          'sent', true, date_trunc('day', now()) + interval '9 hours 15 minutes' - interval '11 hours');

  -- ---------- incident register (all notices sent on time) ----------
  insert into public.incidents (centre_id, child_id, reported_by, occurred_at, description, action_taken, is_serious, parent_notified_at) values
    (c_centre, c_ruby,  u_mia,  now() - interval '7 days',  'Ruby tripped on the edge of the sandpit and grazed her left knee.', 'Cleaned with saline, applied a bandaid and comforted. Returned to play.', false, now() - interval '7 days' + interval '2 hours'),
    (c_centre, c_oscar, u_mia,  now() - interval '15 days', 'Oscar had a mild rash on his arms after outdoor play. No breathing symptoms.', 'Monitored for 30 minutes, no further reaction. Parent informed at pickup.', false, now() - interval '15 days' + interval '4 hours'),
    (c_centre, c_isla,  u_sara, now() - interval '24 days', 'Isla bumped her forehead on a table corner during group time. Small red mark, no loss of consciousness.', 'Cold pack, head injury observation for 2 hours.', false, now() - interval '24 days' + interval '30 minutes');

  -- ---------- regulation update waiting for the owner ----------
  insert into public.regulation_updates (centre_id, title, summary, source_url, published_on, status, match_terms, affected_summary)
  values (c_centre, 'Safe sleep guidance review',
          'New safe sleep guidance may affect the centre’s Sleep and Rest Policy. Review current sleep and rest procedures against the latest official guidance and your service’s approved policy.',
          'https://www.acecqa.gov.au/nqf/national-law-regulations/national-regulations', current_date - 7, 'new', '{sleep}',
          'Sleep and rest policy review · Policies & Procedures');

  -- ---------- AI-suggested checklist, waiting for Sara to approve ----------
  perform public._generate_checklist(c_centre);

  -- ---------- audit evidence already on file (verified by Sara) ----------
  -- Evacuation drill is out of date (quarterly, last one 100 days ago) and authorisation records are missing:
  -- the audit agent picks both up once Sara approves the checklist. Sun protection policy is due for renewal soon.
  set constraints all immediate;
  alter table public.evidence disable trigger evidence_completes_rehearsal;
  set constraints all deferred;
  insert into public.evidence (centre_id, checklist_item_id, title, recorded_on, uploaded_by, status, verified_by, verified_at, source, note, created_at)
  select c_centre, ci.id, e.title, current_date - e.days, u_sara, 'verified', u_sara, now() - make_interval(days => e.days - 1), 'seed', 'Demo record', now() - make_interval(days => e.days)
  from (values
    ('evacuation', 'Evacuation drill: all rooms, 4 min 10 s', 100),
    ('premises',   'Weekly premises and playground safety checklist', 5),
    ('emergency',  'Emergency procedures, contacts and floor plan (displayed)', 150),
    ('sun',        'Sun Protection Policy (reviewed)', 345),
    ('sleep',      'Sleep and Rest Policy and risk assessment', 210)
  ) as e(item_key, title, days)
  join public.checklist_items ci on ci.centre_id = c_centre and ci.item_key = e.item_key and ci.is_active;
  set constraints all immediate;  -- run the queued requirement checks before changing the table
  alter table public.evidence enable trigger evidence_completes_rehearsal;
  set constraints all deferred;

  -- ---------- AI agent key (Vercel: BEEHIVE_AGENT_KEY) ----------
  insert into public.agent_keys (centre_id, key_hash, created_by)
  values (c_centre, encode(sha256(convert_to(v_key, 'UTF8')), 'hex'), u_sara);
  perform set_config('beehive.demo_agent_key', v_key, false);
end $$;

-- Copy this key into Vercel as BEEHIVE_AGENT_KEY (shown once; re-run this file to get a new one).
select 'Demo centre ready. Logins: sara@beehive.demo / priya@beehive.demo / mia@beehive.demo, password Beehive2026!' as done,
       current_setting('beehive.demo_agent_key') as agent_key;
